T("A Suite look, font, minimum height and position for Blizzard dialogs, marked resurrection offers, the item quality written on loot toasts and gold-framed money toasts.", "Aspetto, carattere, altezza minima e posizione della Suite per i dialoghi Blizzard, offerte di resurrezione evidenziate, qualità dell'oggetto scritta sulle notifiche di bottino e notifiche di denaro con cornice dorata.")
T("A bar cannot attach to itself.", "Una barra non può agganciarsi a se stessa.")
T("A bar cannot send cooldowns to itself.", "Una barra non può inviare i recuperi a se stessa.")
T("A cinematic Suite screen with your character while you are AFK. Move or use /afk to return.", "Una schermata cinematografica della Suite con il tuo personaggio mentre sei AFK. Muoviti o usa /afk per tornare.")
T("A class in your group can provide this buff.", "Una classe del tuo gruppo può fornire questo beneficio.")
T("A clean minimap in its own frame: size, shape, border, zoom, Blizzard buttons, an addon button drawer and information texts. Blizzard's minimap buttons keep working.", "Una minimappa pulita in un riquadro dedicato: dimensione, forma, bordo, zoom, pulsanti Blizzard, un cassetto per i pulsanti degli addon e testi informativi. I pulsanti della minimappa di Blizzard continuano a funzionare.")
T("A click-through surface follows each Blizzard chat window. Blizzard and MSUF Edit Mode keep their normal move and resize controls.", "Una superficie che lascia passare i clic segue ogni finestra della chat di Blizzard. La Modalità modifica di Blizzard e quella di MSUF mantengono i normali controlli di spostamento e ridimensionamento.")
T("A colored plate sits behind the map and its border. Padding extends it beyond the map edge.", "Una lastra colorata si trova dietro la mappa e il suo bordo. Il margine interno la estende oltre il bordo della mappa.")
T("A compact, movable history of your recent successful spells.", "Una cronologia compatta e mobile dei tuoi recenti incantesimi riusciti.")
T("A frame-rate readout can sit below the strip or on its own, placed in MSUF Edit Mode. The MSUF Suite FPS key binding shows or hides it for this session, in combat too; a new choice here replaces that session switch.", "Un indicatore dei fotogrammi può stare sotto la barra o a parte, posizionato nella modalità modifica di MSUF. Il tasto FPS di MSUF Suite lo mostra o lo nasconde per questa sessione, anche in combattimento; una nuova scelta qui sostituisce quell'impostazione di sessione.")
T("A movable strip for critical strike, haste, mastery and versatility.", "Una striscia mobile per colpo critico, rapidità, maestria e versatilità.")
T("A movable summary after a Mythic+ run or raid boss kill.", "Un riepilogo spostabile dopo una spedizione Mitica+ o la sconfitta di un boss d'incursione.")
T("A ring around the mouse pointer that is easy to spot, optionally filled by your global cooldown or cast.", "Un anello ben visibile intorno al puntatore del mouse, riempito a scelta dal tuo tempo di recupero globale o dal tuo lancio.")
T("A ring around the mouse pointer that makes it easy to find. Pick its shape, size, color, an optional short trail and a centre dot; No ring keeps only the dot or the progress fill. The camera mode shows ring, dot and trail only while you hold a mouse button down on the game world to turn the camera. The highlight follows the pointer only while something is shown, and it moves nothing while the pointer rests.", "Un anello attorno al puntatore del mouse per trovarlo facilmente. Scegli forma, dimensione, colore, una breve scia e un punto centrale; «Nessun anello» lascia solo il punto o il riempimento di avanzamento. La modalità telecamera mostra anello, punto e scia solo mentre tieni premuto un tasto del mouse sul mondo di gioco per girare la telecamera. L'evidenziazione segue il puntatore solo quando mostra qualcosa e non sposta nulla mentre il puntatore è fermo.")
T("A small summary sits beside the Character tab of your character sheet and leaves with it. It lists your gear with gem sockets and how many are filled, open ones in amber (click a line to open socketing), the total durability of your gear and, if you like, your PvP item level. Its buttons open the Great Vault and the current expansion page. It updates while the sheet is open, at most once per frame.", "Un piccolo riepilogo si trova accanto alla scheda Personaggio e scompare con essa. Elenca l'equipaggiamento con incavi e quanti sono pieni, quelli aperti in ambra (clicca una riga per incastonare), la durabilità totale dell'equipaggiamento e, se vuoi, il livello oggetto PvP. I suoi pulsanti aprono il Grande Forziere e la pagina dell'espansione attuale. Si aggiorna mentre la scheda è aperta, al massimo una volta per fotogramma.")
T("A soft light behind the map, independent of the border and artwork.", "Una luce soffusa dietro la mappa, indipendente dal bordo e dalla grafica.")
T("A summary with gem sockets, durability, PvP item level and Great Vault and expansion buttons, durability on the model, cropped slot icons and item levels on equipment choices.", "Un riepilogo con incavi, durabilità, livello oggetto PvP e pulsanti per il Grande Forziere e l'espansione, durabilità sul modello, icone degli slot ritagliate e livelli oggetto nella scelta dell'equipaggiamento.")
