T("Accept and turn in quests automatically. Hold Shift to pause. Reward choices and quests with a money cost stay manual.", "Accetta e consegna automaticamente le missioni. Tieni premuto Maiusc per mettere in pausa. Le scelte delle ricompense e le missioni con un costo in denaro restano manuali.")
T("Accept guild members", "Accetta membri della gilda")
T("Accept only ordinary party invitations from the relationship types you select. Invites remain manual in combat, while grouped, during queue-loss or quest-session confirmations, or when Blizzard asks you to choose a role. The native popup handles the final action.", "Accetta solo i normali inviti al gruppo inviati dalle persone selezionate. Gli inviti restano manuali in combattimento, se sei già in un gruppo, se potresti perdere una coda o una conferma di sessione di missione, oppure se Blizzard ti chiede di scegliere un ruolo. La finestra di Blizzard esegue l'azione finale.")
T("Accept ordinary party invites from selected friends or guild members when no queue or confirmation would be lost.", "Accetta i normali inviti al gruppo degli amici o dei membri della gilda selezionati, purché non si perda una coda o una conferma.")
