T("Adds automatic collection on top of Blizzard's own Auto Loot setting, which stays unchanged. Locked slots and confirmations stay manual.", "Aggiunge la raccolta automatica all'impostazione Bottino automatico di Blizzard, che resta invariata. Gli slot bloccati e le conferme restano manuali.")
T("Adds guild rank, the hovered unit's target, item levels, the unit's current mount and item or spell details to Blizzard's main tooltip, and can show player names without titles. Your own item level and the one of the unit open in the Inspect window need no request. Item levels of other hovered players are a separate choice that sends inspect requests: at most one per hover, never while the Inspect window or another inspect is busy. Mounts are read once when a unit tooltip opens, out of combat; a change appears on the next hover. Place the fixed corner in MSUF Edit Mode; the cursor offsets apply to the cursor anchor.", "Aggiunge al tooltip principale di Blizzard il grado di gilda, il bersaglio dell'unità, i livelli oggetto, la cavalcatura attuale dell'unità e dettagli di oggetti o incantesimi, e può mostrare i nomi dei giocatori senza titoli. Il tuo livello oggetto e quello dell'unità aperta nella finestra di ispezione non richiedono alcuna richiesta. I livelli oggetto degli altri giocatori sotto il cursore sono un'opzione separata che invia richieste di ispezione: al massimo una per passaggio, mai mentre la finestra di ispezione o un'altra ispezione è occupata. Le cavalcature vengono lette una volta all'apertura di un tooltip di unità, fuori dal combattimento; un cambio appare al passaggio successivo. Posiziona l'angolo fisso nella modalità modifica di MSUF; gli scostamenti del cursore valgono per l'ancoraggio al cursore.")
T("Adds the current-season Mythic+ score to the main tooltip of another player when Blizzard provides a public score. Unknown or restricted scores stay hidden.", "Aggiunge il punteggio Mythic+ della stagione corrente al tooltip principale di un altro giocatore quando Blizzard fornisce un punteggio pubblico. I punteggi sconosciuti o limitati rimangono nascosti.")
T("Adjust the glass effect while keeping your colors and window coverage.", "Regola l'effetto vetro mantenendo i tuoi colori e la copertura delle finestre.")
T("Adventure Guide", "Guida all'avventura")
T("After a completed Mythic+ run or successful raid encounter, show the public result values in a separate card. Choose which figures appear and how long the card stays open. The last result can be reopened here. Combat delays the card until it is safe to show.", "Dopo una spedizione Mitica+ completata o un incontro d'incursione vinto, mostra i risultati pubblici in una scheda separata. Scegli i dati da mostrare e per quanto tempo tenerla aperta. Qui puoi riaprire l'ultimo risultato. Il combattimento ritarda la scheda finché può essere mostrata in sicurezza.")
