T("An MSUF-owned objective tracker with grouped, readable entries.", "Un elenco obiettivi gestito da MSUF, con voci raggruppate e leggibili.")
T("An adjacent button opens a small menu for expansion, Great Vault, Adventure Guide and world map pages. Blizzard's landing button keeps its own click behavior. Menu actions are disabled in combat.", "Un pulsante accanto a quello di Blizzard apre un piccolo menu per espansione, Gran Banca, Guida alle avventure e mappa del mondo. Il pulsante originale di Blizzard mantiene il proprio comportamento. Le azioni del menu sono disabilitate in combattimento.")
T("An empty allow-list includes every quest. Separate quest IDs with spaces or commas. Daily and weekly exclusions leave a quest manual if its frequency cannot be read. Existing profiles keep their previous behavior until you enable an exclusion.", "Una lista consentiti vuota include tutte le missioni. Separa gli ID delle missioni con spazi o virgole. Le esclusioni giornaliere e settimanali lasciano manuale una missione se non se ne può leggere la frequenza. I profili esistenti mantengono il comportamento precedente finché non attivi un'esclusione.")
T("Animated color flashes that celebrate a level, an achievement or Bloodlust, at random times if you like, and can spin the Suite action bars once.", "Lampi di colore animati che festeggiano un livello, un'impresa o Brama di Sangue, anche in momenti casuali se vuoi, e possono far ruotare una volta le barre delle azioni della Suite.")
