T("At a trainer, review the count and combined gold cost before buying. The button learns only abilities already available at confirmation, checks each step again, and stops when the trainer closes, combat starts or the list changes. Profession choices and rank steps stay manual.", "Presso un istruttore, controlla il numero di abilità e il costo totale in oro prima di acquistare. Il pulsante apprende solo le abilità già disponibili al momento della conferma, ricontrolla ogni passaggio e si ferma se chiudi l'istruttore, inizi un combattimento o l'elenco cambia. Le scelte di professione e i passaggi di grado restano manuali.")
