T("Blizzard keeps every original font size and style flag.", "Blizzard mantiene ogni dimensione del carattere e attributo di stile originali.")
T("Blizzard keeps its text sizes and outlines.", "Blizzard mantiene le proprie dimensioni del testo e i contorni.")
T("Blizzard keeps the button artwork, clicks, tooltips, enabled states and notifications. Optional glyph artwork is available in the detail controls. Visual changes apply outside combat only.", "Blizzard mantiene grafica dei pulsanti, clic, tooltip, stati di attivazione e notifiche. I glifi opzionali sono disponibili nei controlli dettagliati. Le modifiche visive si applicano solo fuori dal combattimento.")
T("Blizzard layout captured", "Disposizione Blizzard acquisita")
T("Blizzard layout imported", "Disposizione Blizzard importata")
T("Blizzard original", "Originale Blizzard")
T("Blizzard owns aggro flashes, progressive highlights and soft target icons. Optional colors tint Blizzard's existing threat textures; its health bar threat color stays under the role-color overlay. Soft target icons also need the nameplate icon switch enabled and a matching soft target in game.", "Blizzard gestisce i lampeggi d'aggro, le evidenziazioni progressive e le icone del bersaglio automatico. I colori opzionali tingono le texture di minaccia esistenti; il colore di minaccia della barra della salute resta sotto il colore del ruolo. Le icone richiedono anche l'attivazione delle icone delle barre dei nomi e un bersaglio automatico corrispondente nel gioco.")
T("Blizzard owns the aura icons and updates. Choose Keep Blizzard setting or Customize for each unit type. Buffs, debuffs and control effects can be selected and dragged separately in the preview. Aura size uses Blizzard's own setting.", "Blizzard gestisce le icone delle aure e i loro aggiornamenti. Scegli Mantieni impostazione Blizzard o Personalizza per ogni tipo di unità. Buff, debuff ed effetti di controllo si possono selezionare e trascinare separatamente nell'anteprima. La dimensione delle aure usa l'impostazione di Blizzard.")
T("Blizzard owns these elements. The rarity icon setting applies to all nameplates; raid target icons are hidden only on enemy plates. Castbar details control Blizzard's own castbar. The preview and live plates use the same switches.", "Blizzard gestisce questi elementi. L'impostazione dell'icona di rarità vale per tutte le barre dei nomi; le icone dei bersagli d'incursione sono nascoste solo sulle barre nemiche. I dettagli della barra di lancio controllano la barra di lancio di Blizzard. L'anteprima e le barre reali usano gli stessi interruttori.")
T("Blizzard personal auras", "Aure personali Blizzard")
T("Blizzard plate size (health bar + elements)", "Dimensione barre dei nomi Blizzard (barra salute + elementi)")
T("Blizzard plate style", "Stile barre dei nomi Blizzard")
T("Blizzard raid target icon on enemy plates", "Icona bersaglio d'incursione Blizzard sulle barre nemiche")
T("Blizzard setting", "Impostazione Blizzard")
T("Blizzard shield", "Scudo Blizzard")
T("Blizzard spell icon", "Icona incantesimo Blizzard")
T("Blizzard supplies the castbar texture, colors, progress and interrupts. Customize its text and details here. Select and move each cast element in the preview; positions apply outside combat.", "Blizzard fornisce texture, colori, avanzamento e interruzioni della barra di lancio. Personalizzane qui il testo e i dettagli. Seleziona e sposta ogni elemento del lancio nell'anteprima; le posizioni si applicano fuori dal combattimento.")
T("Blizzard supplies the icons. The Suite keeps its own button plates, bar frame and spacing. Native clicks, tooltips and notifications stay intact.", "Blizzard fornisce le icone. La Suite mantiene le proprie piastre dei pulsanti, la cornice della barra e la spaziatura. Clic, tooltip e notifiche originali restano intatti.")
T("Blizzard supplies the name and health values. Mapko requests full enemy plates and both health values so normal enemies show text too. Width and height change only the enemy health bar in pixels; 0 keeps the selected bar dimensions. Backdrop, border and role fill are separate live skin layers in the preview; right-click a layer for its setting. Role colors use the saved palette; mana is only a caster hint. Open the three-dot menu here or Nameplates in MSUF Colors to change the palette.", "Blizzard fornisce nome e valori di salute. Mapko richiede barre dei nomi nemiche complete ed entrambi i valori di salute, così anche i nemici normali mostrano il testo. Larghezza e altezza modificano solo la barra della salute nemica in pixel; 0 mantiene le dimensioni scelte. Sfondo, bordo e riempimento del ruolo sono livelli separati nell'anteprima; clicca con il destro su un livello per aprirne l'impostazione. I colori dei ruoli usano la tavolozza salvata; il mana è solo un indizio per gli incantatori. Apri il menu con tre punti qui o Barre dei nomi in Colori MSUF per cambiare tavolozza.")
T("Blizzard symbols", "Simboli Blizzard")
T("Blizzard window controls", "Controlli finestre Blizzard")
T("Blizzard windows", "Finestre Blizzard")
T("Blizzard yellow and chat system text", "Giallo Blizzard e testo di sistema della chat")
T("Blizzard's Cooldown Manager stops completely. While your MSUF frames follow its bars, MSUF keeps it running invisibly.", "Il Gestore tempi di recupero di Blizzard si ferma del tutto. Finché i tuoi riquadri MSUF seguono le sue barre, MSUF lo mantiene attivo in modo invisibile.")
T("Blizzard's bars keep running, invisible, so frames that other addons attach to them stay in place.", "Le barre di Blizzard restano attive, invisibili, così i riquadri che altri addon vi agganciano restano al loro posto.")
