T("Blizzard's original Micro Bar and buttons. Use Blizzard Edit Mode to move it.", "La barra del micromenu e i pulsanti originali di Blizzard. Usa la Modalità modifica di Blizzard per spostarla.")
T("Blizzard's own buttons stay functional. The row is their starting position; drag each icon freely in the preview.", "I pulsanti di Blizzard restano funzionanti. La riga è la loro posizione iniziale; trascina liberamente ogni icona nell'anteprima.")
T("Blizzard's own cooldown swipe fills the ring: the global cooldown after each ability, and casts or channels while they run. A cast takes the place of the global cooldown until it ends; the bright edge marks how far the cast has come.", "L'animazione di ricarica di Blizzard riempie l'anello: il tempo di recupero globale dopo ogni abilità e i lanci o le canalizzazioni mentre durano. Un lancio prende il posto del tempo di recupero globale finché non termina; il bordo luminoso indica a che punto è.")
