T("Bounded named-root traversal\nDedicated visual-only Edit Mode coverage\nExplicit secure controls remain untouched\nBlizzard frames keep their parents and scripts; only Suite-made selection indicators move\nNo polling or tickers; OnUpdate runs only while a window corner is dragged", "Attraversamento limitato delle radici con nome\nCopertura dedicata e solo visiva della Modalità modifica\nI controlli protetti espliciti restano intatti\nI frame Blizzard mantengono genitori e script; si spostano solo gli indicatori di selezione creati dalla Suite\nNessun polling o ticker; OnUpdate gira solo mentre si trascina un angolo della finestra")
