T("Bubbles outside instances can take the MSUF look; Blizzard locks the ones inside instances. Each source keeps Blizzard's look or uses the MSUF one: the shared look or its own font, size, colors, spacing and width. A bubble is matched to the line it shows right after that line arrives. Turning bubbles off inside instances uses Blizzard's bubble settings and gives them back when you leave or turn it off.", "I fumetti fuori dalle istanze possono avere lo stile MSUF; Blizzard blocca quelli dentro le istanze. Ogni fonte mantiene lo stile di Blizzard o usa quello di MSUF: lo stile comune o il proprio carattere, dimensione, colori, spaziature e larghezza. Un fumetto viene abbinato alla riga che mostra subito dopo l'arrivo di quella riga. Disattivare i fumetti nelle istanze usa le impostazioni dei fumetti di Blizzard e le ripristina quando esci o disattivi l'opzione.")
