T("Choose %s for \"%s\".", "Scegli %s per «%s».")
T("Choose Clean Modern, Midnight Blue, MSUF Forever Glass, Midnight Dark or Class Style for Skinning and enabled Suite modules. Modules enabled later inherit it.", "Scegli Moderno essenziale, Midnight Blue, Vetro MSUF Forever, Midnight Dark o Stile di classe per le skin e i moduli attivi della Suite. I moduli attivati in seguito lo ereditano.")
T("Choose Clean Modern, Midnight Blue, Midnight Dark, MSUF Forever or Class Style. This changes only the bag window colors and opacity; item slots and Blizzard bag actions remain intact.", "Scegli Moderno essenziale, Midnight Blue, Midnight Dark, MSUF Forever o Stile di classe. Cambia solo i colori e l'opacità delle borse; gli scomparti e le azioni Blizzard restano invariati.")
T("Choose Clean Modern, Midnight Blue, neutral Midnight Dark glass or MSUF Forever's dark gold frame. All use MSUF's bar texture and font. Turn the 20 XP divisions on or off. The lower line can show session gain, XP per hour and time to level. Move or resize the bar in MSUF Edit Mode; its popup edits X, Y, width, height and scale. Hover for exact values. A session survives /reload and starts fresh on the next login.", "Scegli il vetro Clean Modern, Midnight Blue, il vetro neutro Midnight Dark o la cornice oro scuro di MSUF Forever. Tutti utilizzano la texture e il carattere della barra di MSUF. Attiva o disattiva le 20 divisioni XP. La linea inferiore può mostrare il guadagno della sessione, gli XP all'ora e il tempo necessario per raggiungere il livello. Sposta o ridimensiona la barra in MSUF Modalità Modifica; il suo popup modifica X, Y, larghezza, altezza e scala. Passa il mouse per i valori esatti. Una sessione sopravvive a /reload e ricomincia da capo all'accesso successivo.")
T("Choose Clean Modern, classic MSUF or the complete Forever factory.", "Scegli Moderno essenziale, MSUF classico o la configurazione completa Forever.")
T("Choose Custom layout to set the order of total, per-second and percent values, then pick spaces, brackets or a separator. The percent switch controls main rows; breakdown rows show available shares. Unavailable shares are omitted. Primary means per second for DPS/HPS and total for other meters. Text settings also apply to headers, details and the floating timer. Slug uses WoW's crisp font renderer with an outline and no shadow. Protected values show without a percentage until combat ends.", "Scegli Disposizione personalizzata per impostare l'ordine dei valori totale, al secondo e percentuale, poi scegli spazi, parentesi o un separatore. L'interruttore della percentuale controlla le righe principali; le righe di dettaglio mostrano le quote disponibili. Le quote non disponibili vengono omesse. Primario significa al secondo per DPS/HPS e totale per gli altri misuratori. Le impostazioni del testo valgono anche per intestazioni, dettagli e timer mobile. Slug usa il renderer di caratteri nitido di WoW con contorno e senza ombra. I valori protetti vengono mostrati senza percentuale fino alla fine del combattimento.")
T("Choose Suite modules", "Scegli i moduli della Suite")
T("Choose a bar to adjust its layout below. The preview uses sample buttons; empty slots and stances can differ in game.", "Scegli una barra per regolarne la disposizione qui sotto. L'anteprima usa pulsanti di esempio; gli slot vuoti e le posture possono differire nel gioco.")
T("Choose a font", "Scegli un carattere")
T("Choose a line, then press Ctrl+C", "Scegli una riga, poi premi Ctrl+C")
T("Choose a look", "Scegli uno stile")
T("Choose a look and when the Suite bar appears. Visibility rules use the Suite layout; Blizzard layout keeps Blizzard's visibility. MSUF Edit Mode reveals the bar for moving.", "Scegli uno stile e quando appare la barra della Suite. Le regole di visibilità usano la disposizione della Suite; la disposizione Blizzard mantiene la visibilità di Blizzard. La Modalità modifica di MSUF mostra la barra per spostarla.")
T("Choose a look below; this sample follows your changes.", "Scegli uno stile qui sotto; questo esempio segue le tue modifiche.")
T("Choose a look, then adjust its colors.", "Scegli uno stile e modificane i colori.")
T("Choose a preset below or fine-tune with the slider.", "Scegli una preimpostazione qui sotto o regola con precisione con il cursore.")
T("Choose a profile that exists in both parts of the suite", "Scegli un profilo presente in entrambe le parti della Suite")
T("Choose a random owned Hearthstone variant for the next click", "Scegli una variante di pietra del ritorno posseduta casuale per il clic successivo")
T("Choose a smaller stack size and make sure the item is unlocked, your cursor is empty and you are out of combat.", "Scegli una pila più piccola e assicurati che l'oggetto non sia bloccato, il cursore sia vuoto e tu sia fuori dal combattimento.")
T("Choose a sound", "Scegli un suono")
T("Choose a style above or change these colors to make a Custom look. Rows update immediately.", "Scegli uno stile sopra o modifica questi colori per creare un aspetto personalizzato. Le righe si aggiornano immediatamente.")
T("Choose a style, font and coverage in minutes. Every deeper control remains available in Expert mode.", "Scegli stile, carattere e copertura in pochi minuti. Tutti i controlli avanzati restano disponibili in modalità Esperto.")
T("Choose a template", "Scegli un modello")
T("Choose an MSUF font, outline, shadow and Smooth, Sharp or Slug rendering. Slug has no shadow. Label, value and warning colors are separate.", "Scegli un carattere MSUF, contorno, ombra e rendering Morbido, Nitido o Slug. Slug non ha ombra. I colori di etichetta, valore e avviso sono separati.")
T("Choose an MSUF or SharedMedia font and bar texture. Font size, outline, shadow, Smooth/Sharp/Slug rendering, bar height and spacing update the HUD immediately. Slug has no shadow.", "Scegli un carattere MSUF o SharedMedia e una texture delle barre. Dimensione del carattere, contorno, ombra, rendering Morbido/Nitido/Slug, altezza delle barre e spaziatura aggiornano subito l'HUD. Slug non ha ombra.")
T("Choose broad UI families. Dedicated secure behavior and semantic artwork remain untouched.", "Scegli ampie famiglie dell'interfaccia. Il comportamento protetto dedicato e la grafica con significato restano intatti.")
T("Choose broker names and discovered currency IDs per place. Select your current-season crest currencies from the native currency list; saved currency selections work after login without visiting an upgrade NPC. Selection order and separator control the crest block. Observed upgrade stages remain available as an alternative after selecting an upgrade item this login. Hearthstone actions require a deliberate click.", "Scegli i nomi dei broker e gli ID delle valute scoperte per ogni posizione. Seleziona le valute degli emblemi della stagione attuale dall’elenco nativo; le selezioni salvate funzionano dopo l’accesso senza visitare un PNG dei potenziamenti. L’ordine di selezione e il separatore controllano il blocco degli emblemi. I livelli di potenziamento osservati restano disponibili come alternativa dopo aver selezionato un oggetto da potenziare durante questa sessione. Le azioni della Pietra del Ritorno richiedono un clic intenzionale.")
T("Choose buffs and consumables to track.", "Scegli i benefici e i consumabili da monitorare.")
T("Choose clean window controls and a complete Micro Bar style, then tune individual artwork only when needed.", "Scegli controlli delle finestre puliti e uno stile completo per la barra micromenu, poi regola le singole grafiche solo se serve.")
T("Choose coverage", "Scegli la copertura")
T("Choose crest currencies", "Scegli le valute degli emblemi")
T("Choose currencies", "Scegli le valute")
T("Choose data for place %d", "Scegli i dati per lo slot %d")
T("Choose each Blizzard popup separately. The feature hides its window when it appears and leaves the underlying game events intact. Combat lockdown can prevent hiding a protected window.", "Scegli ciascun popup Blizzard separatamente. La funzione nasconde la sua finestra quando appare e lascia intatti gli eventi di gioco sottostanti. Il blocco del combattimento può impedire di nascondere una finestra protetta.")
T("Choose individual recurring UI errors to hide with Blizzard's own message filter.", "Scegli singoli errori ricorrenti dell'interfaccia utente da nascondere con il filtro dei messaggi di Blizzard.")
T("Choose observed seasonal stages", "Scegli i livelli stagionali osservati")
T("Choose one font for Blizzard UI text. Existing sizes, outlines, shadows and accessibility scaling are preserved.", "Scegli un carattere per il testo dell'interfaccia Blizzard. Dimensioni, contorni, ombre e scala di accessibilità esistenti vengono mantenuti.")
T("Choose the detailed character view and its extra information. Changing the view reloads the UI.", "Scegli la vista dettagliata del personaggio e le sue informazioni aggiuntive. Cambiare la vista ricarica l'interfaccia.")
T("Choose the dungeon difficulties where MSUF starts the combat log. Mythic+ begins when the keystone starts.", "Scegli le difficoltà delle spedizioni in cui MSUF avvia il registro di combattimento. In Mitica+ inizia quando si attiva la chiave del potere.")
T("Choose the information shown in each bar.", "Scegli le informazioni mostrate in ogni barra.")
T("Choose the map shape, then adjust its border and outer shadow.", "Scegli la forma della mappa, poi regolane il bordo e l'ombra esterna.")
T("Choose the raid difficulties where MSUF starts the combat log.", "Scegli le difficoltà delle incursioni in cui MSUF avvia il registro di combattimento.")
T("Choose the shared button colors and frame. Layout, bindings and visibility stay as set. Changing an individual color switches the label to Custom.", "Scegli i colori e la cornice condivisi dei pulsanti. Disposizione, assegnazioni dei tasti e visibilità restano come impostate. Cambiare un singolo colore imposta l'etichetta su Personalizzato.")
T("Choose the values shown on each bar.", "Scegli i valori mostrati su ogni barra.")
T("Choose what the Suite tracker lists and when it steps aside.", "Scegli cosa elenca il tracciamento Suite e quando si fa da parte.")
T("Choose where recent actions appear. Delves have their own switch; battlegrounds and arenas share one, and other scenarios follow Outside instances. Where the tracker is switched off, it does not listen to your casts.", "Scegli dove compaiono le azioni recenti. Le profondità hanno un interruttore proprio; campi di battaglia e arene ne condividono uno, e gli altri scenari seguono «Fuori dalle istanze». Dove il registro è disattivato, non ascolta i tuoi lanci.")
T("Choose which Blizzard interfaces receive the skin. Blizzard keeps their interactions.", "Scegli quali interfacce di Blizzard ricevono la skin. Blizzard mantiene le loro interazioni.")
T("Choose your bars", "Scegli le tue barre")
T("Choose your profile", "Scegli il tuo profilo")
T("Choosing a look updates Skinning and every enabled Suite module. Modules enabled later inherit it. New skin profiles start with %s.", "Scegliere uno stile aggiorna Skin e ogni modulo attivo della Suite. I moduli attivati in seguito lo ereditano. I nuovi profili skin partono con %s.")
T("Cinematic confirmation can be skipped after you choose to exit. Automatic skipping is a separate option and also skips movies. Both stay inactive during combat, and a vehicle sequence always keeps its exit confirmation. Hide tutorials while this helper is enabled, prefill the DELETE word while keeping the final confirmation manual, hide only the successful screenshot notice, or open your character window at merchants on the tab you used last. At the auction house, Blizzard's filter button is marked while Current Expansion Only is off; tick it there once and Blizzard keeps it for this character.", "La conferma può essere saltata dopo che scegli di uscire. Il salto automatico è un'opzione separata e include anche i filmati. Entrambe restano inattive in combattimento e una sequenza su veicolo mantiene sempre la sua conferma di uscita. L'assistente può nascondere i tutorial, compilare la parola di eliminazione lasciando manuale la conferma finale, nascondere solo l'avviso di schermata acquisita o aprire la finestra del personaggio dai mercanti, sull'ultima scheda usata. Alla casa d'aste, il pulsante dei filtri di Blizzard viene evidenziato finché «Solo espansione attuale» è disattivato; spuntalo lì una volta e Blizzard lo mantiene per questo personaggio.")
T("Cinematic zone and event announcements in the Suite look.", "Annunci cinematografici di zone ed eventi nello stile della Suite.")
