T("Clean Modern", "Moderno essenziale")
T("Clean Modern  ·  Suite default", "Moderno essenziale · predefinito di Suite")
T("Clean Modern is the Retail default; MSUF Forever is the Forever default. Midnight Blue keeps the original blue glass. Open a section's three-dot menu to change its colors, or use MSUF Colors for the full palette. Your own color changes become Custom.", "Moderno essenziale è il predefinito di Retail; MSUF Forever è quello di Forever. Midnight Blue mantiene il vetro blu originale. Apri il menu con tre punti di una sezione per cambiarne i colori, oppure usa Colori MSUF per l'intera tavolozza. Le tue modifiche diventano Personalizzato.")
T("Clean Modern uses matte panels with white accents. Midnight Blue keeps the original blue palette. Midnight Dark uses neutral charcoal glass; MSUF Forever retains its muted gold. Color changes become Custom.", "Moderno essenziale usa pannelli opachi con accenti bianchi. Midnight Blue conserva la tavolozza blu originale. Midnight Dark usa vetro antracite neutro; MSUF Forever mantiene l'oro tenue. Le modifiche ai colori diventano Personalizzato.")
T("Clean Modern · Suite and Skin, MSUF frames retained", "Moderno essenziale · Suite e Skin, riquadri MSUF mantenuti")
T("Clean Modern, Midnight Blue, Midnight Dark and MSUF Forever are complete looks in Style. Color palettes here change colors only; use Expert mode for every UI state.", "Moderno essenziale, Midnight Blue, Midnight Dark e MSUF Forever sono stili completi in Stile. Qui le tavolozze cambiano solo i colori; usa la modalità Esperto per ogni stato dell'interfaccia.")
T("Clean Studio", "Studio pulito")
T("Clean profile created", "Profilo vuoto creato")
T("Clear", "Cancella")
T("Clear new mount markers", "Cancella i nuovi indicatori di cavalcatura")
T("Clear new mount, pet and toy fanfares acquired while this helper is active.", "Rimuovi i contrassegni «Novità» da cavalcature, mascotte e giocattoli ottenuti mentre questa funzione è attiva.")
T("Clear new pet markers", "Rimuovi i contrassegni «Novità» dalle mascotte")
T("Clear new toy markers", "Cancella nuovi segnalini giocattolo")
T("Clear only new mount, pet and toy fanfares acquired while this helper is active. Your collection entries remain available. Each collection type can be switched off independently.", "Rimuovi solo i contrassegni «Novità» da cavalcature, mascotte e giocattoli ottenuti mentre questa funzione è attiva. Gli elementi della collezione restano disponibili. Puoi disattivare separatamente ogni tipo di collezione.")
T("Clear previous mark", "Cancella il segnalino precedente")
T("Clear recent items", "Svuota gli oggetti recenti")
T("Clear run history", "Cancella la cronologia delle spedizioni")
T("Clear saved character gold", "Cancella i dati salvati sull'oro dei personaggi")
T("Clear saved chat history", "Cancella la cronologia della chat salvata")
T("Clear saved selection", "Cancella la selezione salvata")
T("Clear selection", "Cancella selezione")
T("Clear the saved chat history of this character in every chat window? This cannot be undone.", "Cancellare la cronologia della chat salvata di questo personaggio in tutte le finestre della chat? Non si può annullare.")
T("Clear the saved gold balances of all your characters and their gold history? This cannot be undone.", "Cancellare l'oro salvato di tutti i tuoi personaggi e la loro cronologia dell'oro? Non si può annullare.")
T("Clear worldmarks", "Rimuovi i segnali sul terreno")
T("Click a bar to open the spell breakdown in the window; hover it for a short tooltip.", "Fai clic su una barra per aprire il dettaglio degli incantesimi nella finestra; passaci sopra il mouse per un breve tooltip.")
T("Click a place to choose its text. Drag the bar in MSUF Edit Mode. Empty places disappear. The Antique Footer preset creates a bag, durability and clock strip on this bar only.", "Fai clic su uno slot per sceglierne il testo. Trascina la barra nella Modalità modifica di MSUF. Gli slot vuoti scompaiono. La preimpostazione Fascia antica crea una striscia con borse, integrità e orologio solo su questa barra.")
T("Click a reminder to cast its spell or use its item. Aura checks run on relevant events; there is no repeating scan.", "Fai clic su un promemoria per lanciare il suo incantesimo o usare il suo oggetto. I controlli delle aure avvengono sugli eventi pertinenti; non c'è alcuna scansione ripetuta.")
T("Click a spell for its settings", "Fai clic su un incantesimo per le sue impostazioni")
T("Click again to delete", "Clicca di nuovo per eliminare")
T("Click for bag options", "Clic per le opzioni delle borse")
T("Click opens the world map", "Il clic apre la mappa del mondo")
T("Click the minimap button for Blizzard's specialization and loot specialization choices. Choices are disabled in combat and the button hides when both menus are turned off.", "Fai clic sul pulsante della minimappa per la specializzazione di Blizzard e le scelte di specializzazione del bottino. Le scelte sono disabilitate in combattimento e il pulsante si nasconde quando entrambi i menu sono disattivati.")
