T("Color flashes with a banner that names the moment: the level you reached, the achievement you earned, or the Bloodlust-type haste spell that you or your pet cast or that reaches you from anyone in your group (read from your own buffs, which the game may keep hidden during restricted fights). Surprise celebrations can come at random times, around the interval you choose. Spinning turns the Suite action bars once around their centre, only outside combat; entering combat stops the turn at once. Achievements your account had already earned stay quiet. MSUF Edit Mode shows the banner for placing it.", "Lampi di colore con un banner che nomina il momento: il livello raggiunto, l'impresa ottenuta o l'incantesimo di celerità come Brama di Sangue lanciato da te o dal tuo famiglio o che ti raggiunge da chiunque nel tuo gruppo (letto dai tuoi benefici, che il gioco può nascondere nei combattimenti con restrizioni). I festeggiamenti a sorpresa possono arrivare in momenti casuali, intorno all'intervallo scelto. La rotazione fa girare una volta le barre delle azioni della Suite attorno al loro centro, solo fuori dal combattimento; entrare in combattimento la ferma subito. Le imprese che il tuo account aveva già restano silenziose. La modalità modifica di MSUF mostra il banner per posizionarlo.")
