T("Copies the active Blizzard spell selection, bar assignment and order into this specialization's five built-in Suite bars. Your defensive and custom bars, other specializations, and Blizzard settings stay as they are. You can undo it.", "Copia la selezione attiva degli incantesimi di Blizzard, l'assegnazione alle barre e l'ordine nelle cinque barre integrate della Suite di questa specializzazione. Le tue barre difensive e personalizzate, le altre specializzazioni e le impostazioni di Blizzard restano come sono. Puoi annullare l'operazione.")
