T("Copies the spells and items you added to this bar to the same bar in your other specializations. Blizzard's entries follow each specialization's own list. You can undo it.", "Copia gli incantesimi e gli oggetti che hai aggiunto a questa barra nella stessa barra delle tue altre specializzazioni. Le voci di Blizzard seguono l'elenco di ciascuna specializzazione. Puoi annullare l'operazione.")
