T("Double-click a search result to open Blizzard's application dialog. With submit on double-click, the second click also signs up with the roles already chosen in that dialog; hold Shift to review it instead. A saved note can appear beside the dialog for copying; it is stored when you finish editing.", "Fai doppio clic su un risultato della ricerca per aprire la finestra di candidatura di Blizzard. Con l'invio al doppio clic, il secondo clic ti candida anche con i ruoli già scelti in quella finestra; tieni premuto Maiusc per controllarla invece. Una nota salvata può comparire accanto alla finestra per essere copiata; viene salvata quando finisci di modificarla.")
T("Double-click a search result to open Blizzard's normal application dialog.", "Fai doppio clic su un risultato di ricerca per aprire la normale finestra di candidatura di Blizzard.")
T("Drag a window by its top edge; drag the bottom-right corner to scale it. The top-right minus button collapses compatible windows to a restore tab. Bags and protected windows keep their native behavior.", "Trascina una finestra dal bordo superiore; trascina l'angolo in basso a destra per ridimensionarla. Il pulsante meno in alto a destra comprime le finestre compatibili in una scheda di ripristino. Le borse e le finestre protette mantengono il comportamento nativo.")
T("Drag announcements in MSUF Edit Mode, or set their timing, scale and exact position here.", "Trascina gli annunci nella Modalità modifica di MSUF o impostane qui tempi, scala e posizione esatta.")
T("Drag or use arrows to move; Shift: 5, Ctrl: 10.", "Trascina o usa le frecce per spostare; Maiusc: 5, Ctrl: 10.")
T("Drag or use arrows to move; click for settings.", "Trascina o usa le frecce per spostare; fai clic per le impostazioni.")
T("Drag the bag title to move it; click for options.", "Trascina il titolo della borsa per spostarla; fai clic per le opzioni.")
T("Drag the bar's edge to move it on screen.", "Trascina il bordo della barra per spostarla sullo schermo.")
T("Drag the reagent bag title while it is open to move it independently. Click the title for bag options. Reset its position in MSUF Edit Mode to follow Blizzard's normal bag layout again.", "Trascina il titolo della borsa dei reagenti mentre è aperta per spostarla separatamente. Fai clic sul titolo per le opzioni delle borse. Reimpostane la posizione nella Modalità modifica di MSUF per seguire di nuovo la normale disposizione delle borse di Blizzard.")
T("Drag the result card in MSUF Edit Mode, or set its screen anchor, width, scale and position here.", "Trascina la scheda dei risultati in modalità Modifica di MSUF, oppure imposta qui ancoraggio, larghezza, scala e posizione.")
T("Drag the title of an open bag to move it. Click the title for bag options. Each bag keeps its own position. Blizzard shows your current gold on the right; the optional Session value on the left shows the change since login and survives /reload. Adjust the combined bag size here or in its MSUF Edit Mode popup. Reset position in Edit Mode returns the window to Blizzard's normal anchor.", "Trascina il titolo di una borsa aperta per spostarla. Fai clic sul titolo per le opzioni delle borse. Ogni borsa mantiene la propria posizione. Blizzard mostra il tuo oro attuale a destra; il valore facoltativo Sessione a sinistra mostra la variazione dal login e sopravvive a /reload. Regola qui la dimensione delle borse unificate o nel relativo popup della Modalità modifica di MSUF. Reimposta posizione nella Modalità modifica riporta la finestra all'ancoraggio normale di Blizzard.")
