T("Drop an item here to add it without moving it.", "Trascina qui un oggetto per aggiungerlo senza spostarlo.")
T("Drop an item onto Pinned items in the category sidebar to keep it at the top of every view. Recent items lists up to 200 item types this character received, also across logins; each leaves the list once it is older than the hours set here, and Clear recent items empties it sooner. Neither action moves or deletes an item.", "Trascina un oggetto su Oggetti fissati nella barra laterale per mantenerlo in cima a ogni vista. Oggetti recenti elenca fino a 200 tipi di oggetti ricevuti da questo personaggio, anche tra un accesso e l'altro; ognuno esce dall'elenco quando supera le ore impostate qui, e Svuota gli oggetti recenti lo svuota prima. Nessuna azione sposta o elimina oggetti.")
