T("Drops this bar's own order and the spells and items you added to it, for this specialization. Spells you removed stay hidden: Show removed spells brings them back. You can undo it.", "Elimina l'ordine proprio di questa barra e gli incantesimi e gli oggetti che le hai aggiunto, per questa specializzazione. Gli incantesimi rimossi restano nascosti: Mostra incantesimi rimossi li riporta indietro. Puoi annullare l'operazione.")
