T("Enter a spell name or ID on MSUF action bars. Its buttons glow from this buff on you. A page change in combat pauses the glow until combat ends.", "Inserisci il nome o l'ID di un incantesimo sulle barre MSUF. I suoi pulsanti brillano in base a questo beneficio su di te. Cambiare pagina in combattimento sospende il bagliore fino alla fine del combattimento.")
T("Enter a talent or spell name or ID, then press Enter. Every required spell must be learned. Empty removes this condition.", "Inserisci il nome o l'ID di un talento o incantesimo, poi premi Invio. Tutti gli incantesimi richiesti devono essere appresi. Lascia vuoto per rimuovere la condizione.")
T("Enter a talent or spell name or ID, then press Enter. The entry is hidden while any excluded spell is learned. Conditions update outside combat.", "Inserisci il nome o l'ID di un talento o incantesimo, poi premi Invio. La voce viene nascosta se conosci uno qualsiasi degli incantesimi esclusi. Le condizioni si aggiornano fuori dal combattimento.")
T("Enter a texture file ID.", "Inserisci un ID file texture.")
T("Enter a valid spell name or ID", "Inserisci un nome o un ID incantesimo valido")
T("Enter a valid talent or spell name or ID.", "Inserisci un nome o ID valido di talento o incantesimo.")
T("Enter up to 200 item IDs. A button appears only at a merchant and previews eligible stacks; clicking it opens a confirmation. The helper checks item identity, quality, value, quest status and bag position again before requesting sales. Equippable items require a separate opt-in.", "Inserisci fino a 200 ID oggetto. Un pulsante appare solo presso un commerciante e visualizza l'anteprima degli stack idonei; cliccandolo si apre una conferma. L'aiutante controlla nuovamente l'identità dell'oggetto, la qualità, il valore, lo stato della missione e la posizione della borsa prima di richiedere la vendita. Gli oggetti equipaggiabili richiedono un consenso esplicito separato.")
T("Enter up to eight spell IDs for movement abilities. When movement begins, the first known, ready and usable spell appears briefly; a shared 20-second cooldown limits notices. Empty IDs do no work. MSUF Edit Mode moves the cue.", "Inserisci fino a otto ID incantesimo per le abilità di movimento. Quando inizia il movimento, appare brevemente il primo incantesimo conosciuto, pronto e utilizzabile; un tempo di recupero condiviso di 20 secondi limita gli avvisi. Gli ID vuoti non funzionano. La modalità modifica di MSUF sposta l'avviso.")
T("Equal", "Uguale")
T("Equipment", "Equipaggiamento")
T("Equipment category", "Categoria equipaggiamento")
T("Equipment choices", "Scelta dell'equipaggiamento")
T("Equipment choices (the list that opens from a gear slot) show the item level on each item, so you can compare without hovering. The arrows beside the gear slots can be hidden; hold Alt over a slot to open its choices.", "La scelta dell'equipaggiamento (l'elenco che si apre da uno slot) mostra il livello di ogni oggetto, così puoi confrontare senza passare il mouse. Le frecce accanto agli slot si possono nascondere; tieni premuto Alt su uno slot per aprirne la scelta.")
T("Equipment item levels appear in the upper right of each slot. Choose a font, outline, shadow and Smooth, Sharp or Slug rendering. Slug has no shadow. Missing item data appears when the client provides it.", "I livelli oggetto dell'equipaggiamento appaiono in alto a destra di ogni slot. Scegli carattere, contorno, ombra e rendering Morbido, Nitido o Slug. Slug non ha ombra. I dati mancanti degli oggetti appaiono quando il client li fornisce.")
