T("Every color has a purpose", "Ogni colore ha uno scopo")
T("Every color, look, geometry, font, icon, Micro Bar, Blizzard skin and HUD setting travels with the profile.", "Ogni impostazione di colore, stile, geometria, carattere, icone, barra micromenu, skin Blizzard e HUD viaggia con il profilo.")
T("Every specialization already has it.", "Tutte le specializzazioni lo hanno già.")
T("Every spell of this bar, unlearned ones included. On a buff bar, Add spells offers received buffs such as Power Infusion and Innervate; Buff on me also accepts a buff aura ID or resolvable name and tracks that ID from any caster. With Show missing buffs off, only active buffs appear. The preview edits entries too: click for options, drag to reorder or onto a bar above, middle-click to remove (with undo). Removed spells stay under Add spells. Lists are kept per specialization.", "Ogni incantesimo di questa barra, inclusi quelli non appresi. Su una barra dei buff, Aggiungi incantesimi offre i buff ricevuti come Infusione di potere e Stimolazione; Buff su di me accetta anche l'ID di un'aura buff o un nome risolvibile e traccia quell'ID da qualsiasi incantatore. Con Mostra buff mancanti attenuati disattivato, appaiono solo i buff attivi. Anche l'anteprima modifica le voci: fai clic per le opzioni, trascina per riordinare o su una barra sopra, clic centrale per rimuovere (con annullamento). Gli incantesimi rimossi restano in Aggiungi incantesimi. Gli elenchi sono salvati per specializzazione.")
