T("Fonts", "Caratteri")
T("Fonts, outlines, shadows and Smooth/Sharp/Slug rendering for keybinds, macro names, counts and cooldown numbers. Sizes are set per bar below. Slug has no shadow.", "Caratteri, contorni, ombre e rendering Morbido/Nitido/Slug per tasti assegnati, nomi delle macro, conteggi e numeri di recupero. Le dimensioni si impostano per barra qui sotto. Slug non ha ombra.")
