T("For Warlocks: show Burning Rush only while its aura is active in combat. Blizzard's native aura container follows the aura; Suite does not scan auras. MSUF Edit Mode shows a sample and moves the cue.", "Per gli Stregoni: mostra Burning Rush solo mentre la sua aura è attiva in combattimento. Il contenitore delle aure di Blizzard segue l'aura; Suite non esegue scansioni delle aure. La modalità modifica di MSUF mostra un esempio e permette di spostare l'avviso.")
T("Forever artwork", "Grafica Forever")
T("Forever factory profile unavailable", "Profilo di fabbrica Forever non disponibile")
T("Forever only. Route times are learned from completed flight-master journeys and kept in this profile. A first journey has no invented estimate. Early landing does not overwrite a full-route time. Intermediate stops come from the native taxi map; its tooltip can preview the route. Land at next stop requests the next available landing point.", "Solo Forever. I tempi dei viaggi completi vengono appresi e conservati nel profilo. Il primo viaggio non ha stime inventate. L’atterraggio anticipato non sovrascrive il tempo completo. Le fermate derivano dalla mappa nativa e la descrizione può mostrare la rotta. «Atterra alla prossima fermata» richiede il prossimo punto disponibile.")
