T("Friendly player display chooses Blizzard's setting, names for all friendly players, names for party / raid only, or health bars. Names only hides Blizzard bars, casts and auras for friendly players; it does not change NPC or enemy plates. Group / outsider in the preview only changes the sample. Blizzard can forbid changes to friendly plates in instances; those frames stay under Blizzard's control.", "Visualizzazione giocatori amichevoli sceglie l'impostazione di Blizzard, i nomi per tutti i giocatori amichevoli, i nomi solo per gruppo / incursione o le barre della salute. Solo nomi nasconde barre, lanci e aure di Blizzard per i giocatori amichevoli; non cambia le barre dei PNG o dei nemici. Gruppo / esterno nell'anteprima cambia solo l'esempio. Blizzard può impedire modifiche alle barre amichevoli nelle istanze; quei riquadri restano sotto il controllo di Blizzard.")
