T("Hide", "Nascondi")
T("Hide Blizzard bag buttons; use the Bag space DataText", "Nascondi pulsanti borse Blizzard; usa il testo informativo Spazio borse")
T("Hide Blizzard's main tooltip in combat, in instances, or for selected item, spell and unit tooltips. MSUF unit and group frame tooltips keep their own visibility settings; aura tooltips keep their Show Tooltip switches. Each choice works independently. A hidden tooltip turns fully transparent, so Blizzard keeps handling it as usual.", "Nascondi il tooltip principale di Blizzard in combattimento, nelle istanze o per i tooltip di oggetti, incantesimi e unità selezionati. I tooltip dei riquadri unità e gruppo di MSUF mantengono le proprie impostazioni di visibilità; quelli delle aure mantengono le proprie opzioni Mostra tooltip. Ogni scelta funziona in modo indipendente. Un tooltip nascosto diventa del tutto trasparente, così Blizzard continua a gestirlo come sempre.")
