T("Hide only the selected error types. Blizzard keeps handling all other messages and their sounds. Each choice remembers and restores its previous display state when you turn it off.", "Nascondi solo i tipi di errore selezionati. Blizzard continua a gestire tutti gli altri messaggi e i relativi suoni. Ogni scelta ricorda e ripristina il suo stato di visualizzazione precedente quando la spegni.")
