T("Hide spell tooltips", "Nascondi i tooltip degli incantesimi")
T("Hide target arrows on friendly plates", "Nascondi frecce bersaglio sulle barre amichevoli")
T("Hide the Suite Micro Bar when any selected condition is true. The health condition uses your character's health; at full health the transparent bar can still receive clicks. MSUF Edit Mode shows the bar for placement. Blizzard layout keeps Blizzard's visibility.", "Nascondi la barra del micromenu della Suite quando una delle condizioni selezionate è vera. La condizione sulla salute usa la salute del tuo personaggio; a salute piena la barra trasparente può comunque ricevere clic. La Modalità modifica di MSUF mostra la barra per posizionarla. La disposizione Blizzard mantiene la visibilità di Blizzard.")
T("Hide the arrows beside gear slots", "Nascondi le frecce accanto agli slot")
T("Hide the charge count at zero", "Nascondi il conteggio cariche a zero")
T("Hide the flight timer", "Nascondi il timer di volo")
T("Hide this bar", "Nascondi questa barra")
T("Hide this bar when any selected condition is true. The health condition uses your character's health. At full health the bar is transparent but can still receive clicks. Edit Mode shows it for placement.", "Nascondi questa barra quando una delle condizioni selezionate è vera. La condizione sulla salute usa la salute del tuo personaggio. A salute piena la barra è trasparente ma può comunque ricevere clic. La Modalità modifica la mostra per posizionarla.")
