T("Hold %s to release spirit", "Tieni premuto %s per liberare lo spirito")
T("Hold Alt to see the ID of an item, spell, creature, quest, currency or temporary weapon enchant on its tooltip, or press Alt while the tooltip is open; the IDs stay until the tooltip is built again. Spell icon IDs and Blizzard's account character currency data are optional, and that data joins an open tooltip when it arrives. No ID or quantity appears when the client keeps it private.", "Tieni premuto Alt per vedere l'ID di un oggetto, incantesimo, creatura, missione, valuta o incantamento temporaneo dell'arma nel suo tooltip, oppure premi Alt a tooltip aperto; gli ID restano finché il tooltip non viene ricostruito. Gli ID delle icone degli incantesimi e i dati di valuta degli altri personaggi forniti da Blizzard sono facoltativi, e questi dati si aggiungono a un tooltip aperto quando arrivano. Nessun ID o quantità appare quando il client li mantiene privati.")
T("Hold Alt to show item, spell, creature, quest, currency and temporary weapon enchant IDs on the main tooltip.", "Tieni premuto Alt per mostrare gli ID di incantesimo di oggetti, incantesimi, creature, missioni, valuta e armi temporanee nella descrizione comando principale.")
T("Hold Midnight Artisan payouts while Shard of Dundun is capped", "Conserva i pagamenti degli artigiani di Midnight al limite di Schegge di Dundun")
T("Hold Shift to pause. Quests with a money cost and quests with a reward choice always stay manual.", "Tieni premuto Maiusc per mettere in pausa. Le missioni con un costo in denaro e quelle con una scelta di ricompensa restano sempre manuali.")
T("Hold the selected key while clicking Release Spirit. The release button stays hidden until you hold it; resurrection and death recap remain available. Choose where to use the protection. Blizzard's automatic release timer is unchanged.", "Tieni premuto il tasto scelto mentre clicchi Rilascia spirito. Il pulsante resta nascosto finché non lo tieni premuto; resurrezione e riepilogo della morte restano disponibili. Scegli dove usare la protezione. Il timer di rilascio automatico di Blizzard resta invariato.")
T("Hold to release", "Tieni premuto per rilasciare")
