T("How cooldown icons react. Single spells can differ: click them in the preview.", "Come reagiscono le icone dei tempi di recupero. I singoli incantesimi possono differire: fai clic su di essi nell'anteprima.")
T("How the icons line up and grow. A free bar's position counts from the screen center; an attached bar's is an offset from its attach point. Excess cooldowns can move past Maximum icons to another enabled cooldown bar. The destination must have overflow off; chained routes are ignored.", "Allineamento e crescita delle icone. La posizione di una barra libera è relativa al centro dello schermo; quella di una barra collegata al suo punto di ancoraggio. I recuperi oltre il massimo di icone possono passare a un'altra barra attiva. La destinazione deve avere il trasferimento dell'eccesso disattivato; le catene vengono ignorate.")
