T("Inside a raid the tracker turns into an encounter view at its usual place: boss name, pull timer, the bosses engaged right now with their health, your best wipe and your fastest kill. Phases come from DBM or BigWigs when one is installed; otherwise the phase stays open. A wipe with more bosses down beats one with fewer, and with the same count the one with less boss health left wins. Each character keeps its own records. Boss health shows only while the client reveals it.", "In incursione l’elenco diventa, nella sua posizione abituale, una vista dello scontro: nome del boss, timer del pull, i boss ingaggiati con la loro salute, il tuo miglior wipe e l’uccisione più rapida. Le fasi arrivano da DBM o BigWigs se uno dei due è installato; altrimenti la fase resta aperta. Un wipe con più boss sconfitti batte uno con meno e, a parità, vince quello con meno salute rimasta ai boss. Ogni personaggio conserva i propri record. La salute dei boss appare solo finché il client la rivela.")
