T("Keep Blizzard grid, or choose one Suite grid, physical bag groups or categories. Use Edit categories in the bag window to create, rename, reorder or disable your categories; drop items onto a sidebar category to assign them. Scroll or use Previous and Next for larger inventories; in combat every slot is shown at once. Combined stack counts are visual only; physical stacks are always restored at the bank, guild bank, mail, trade, auction house and merchant.", "Mantieni la griglia Blizzard o scegli una griglia Suite, gruppi per borsa fisica o categorie. Usa Modifica categorie nella finestra delle borse per creare, rinominare, riordinare o disattivare le categorie; trascina gli oggetti su una categoria laterale per assegnarli. Scorri o usa Precedente e Successivo per inventari grandi; in combattimento tutti gli spazi vengono mostrati insieme. I conteggi combinati sono solo visivi; le pile reali vengono sempre ripristinate in banca, nella banca di gilda, alla posta, negli scambi, alla casa d'aste e dai mercanti.")
