T("Lightweight meter windows for damage, healing, interrupts, dispels, deaths and damage taken. They read the client's own combat data; Blizzard's meter window stays hidden while this module is active.", "Finestre leggere del misuratore per danni, cure, interruzioni, dissoluzioni, morti e danni subiti. Leggono i dati di combattimento del client; la finestra del misuratore di Blizzard resta nascosta mentre questo modulo è attivo.")
T("Lilac", "Lilla")
T("Limit the whole highlight to combat, to instances or to the open world, then give the pointer ring, the global cooldown and the cast fill their own combat rule. Nothing follows the pointer while it is hidden.", "Limita tutta l'evidenziazione al combattimento, alle istanze o al mondo aperto, poi dai all'anello del puntatore, al tempo di recupero globale e al riempimento del lancio una regola di combattimento propria. Nulla segue il puntatore mentre è nascosta.")
