T("List group pets", "Elenca i famigli del gruppo")
T("Lists carried gem types beside Blizzard's socket window. Inspect each gem with its normal bag tooltip and confirm compatibility in the native socket window before applying it.", "Elenca i tipi di gem trasportati accanto alla finestra del socket di Blizzard. Ispeziona ogni gemma con il tooltip della sua normale borsa e conferma la compatibilità nella finestra del socket nativo prima di applicarla.")
T("Lists the casts of attackable enemy nameplates while you are in a five-player dungeon, oldest first; the game runs each bar and timer. The game keeps spell, target, marker and interrupt details hidden from addons, so casts are never sorted or filtered by them: fading or hiding uses the game's important-spell flag (a hidden cast keeps its place in the list), raid markers sit on the spell icon, and the ready mark, an edge stripe or the whole bar, shows on interruptible casts while your interrupt is off cooldown. Dimming checks four times a second whether your interrupt reaches each listed enemy; a cast it cannot check stays bright. The interrupt is found from your talents and pet unless you enter a spell ID. MSUF Edit Mode shows sample casts for placing the list.", "Elenca i lanci dei nemici attaccabili con barra del nome mentre sei in una spedizione per cinque giocatori, dal più vecchio; il gioco gestisce ogni barra e ogni timer. Il gioco nasconde agli addon incantesimo, bersaglio, segnalino e possibilità di interruzione, quindi i lanci non vengono mai ordinati né filtrati in base a essi: attenuare o nascondere usa il contrassegno di incantesimo importante del gioco (un lancio nascosto mantiene il suo posto nell'elenco), i segnalini dell'incursione stanno sull'icona dell'incantesimo e il segno di pronto, una striscia sul bordo o tutta la barra, compare sui lanci interrompibili finché la tua interruzione non è in ricarica. Lo scurimento controlla quattro volte al secondo se la tua interruzione raggiunge ogni nemico elencato; un lancio che non si può controllare resta chiaro. L'interruzione è rilevata da talenti e famiglio, a meno che tu non inserisca un ID incantesimo. La modalità modifica di MSUF mostra lanci di esempio per posizionare l'elenco.")
T("Lists the casts of enemy nameplates in five-player dungeons, oldest first, with timers the game runs.", "Elenca i lanci delle barre dei nomi nemiche nelle spedizioni per cinque giocatori, dal più vecchio, con timer gestiti dal gioco.")
