T("MSUF icons replace the scattered Blizzard chat controls. Friends, channels, text to speech and the chat menu keep their Blizzard actions; the bottom icon jumps to the newest message. Turn this off to restore the native buttons.", "Le icone MSUF sostituiscono i controlli sparsi della chat di Blizzard. Amici, canali, sintesi vocale e il menu della chat mantengono le loro azioni Blizzard; l'icona in basso salta al messaggio più recente. Disattiva questa opzione per ripristinare i pulsanti nativi.")
