T("MSUF look for speech bubbles outside instances", "Stile MSUF per i fumetti fuori dalle istanze")
T("MSUF looks use Suite glyphs and a player portrait. Blizzard keeps every button action and tooltip.", "Gli stili MSUF usano i glifi della Suite e un ritratto del giocatore. Blizzard mantiene ogni azione e tooltip dei pulsanti.")
