T("MSUF stops only a log it started. A log that was already on stays on. Re-entering selected content cancels a pending stop. WoW writes the log in its Logs folder.", "MSUF interrompe solo un registro che ha avviato. Un registro già attivo resta attivo. Rientrare nei contenuti selezionati annulla un'interruzione in sospeso. WoW scrive il registro nella sua cartella Logs.")
