T("Mainline covers Rogue poisons, this season's flasks, augment runes and weapon oils, and the Well Fed food buff. Each category clicks the first matching item in your bags; an item you enter for it is tried first. Food is found in your bags by the game's eating spells: the food you enter comes first, then the newest one. With the gray reminder on, a category with nothing left stays visible without a click action. Assassination prefers Deadly Poison; Outlaw and Subtlety prefer Instant Poison. Dragon-Tempered Blades allows two poisons per category. Oils target equipped weapons; known Shaman or Paladin imbues suppress automatic oils.", "Mainline copre i veleni del Ladro, le fiasche, le rune di potenziamento e gli oli per armi di questa stagione, oltre al beneficio del cibo Ben nutrito. Ogni categoria usa al clic il primo oggetto adatto nelle borse; un oggetto indicato per essa viene provato per primo. Il cibo viene trovato nelle borse tramite gli incantesimi di pasto del gioco: prima quello indicato, poi il più recente. Con il promemoria grigio, una categoria esaurita resta visibile senza azione al clic. Assassinio preferisce Veleno Mortale; Fuorilegge e Scaltrezza preferiscono Veleno Istantaneo. Lame Temprate dai Draghi consente due veleni per categoria. Gli oli si applicano alle armi equipaggiate; gli incantamenti noti di Sciamano o Paladino escludono gli oli automatici.")
