T("Mapko uses Modern plates, Medium size and the same bar dimensions on Retail and Forever. Guild names and titles also affect names in the world. Bind Toggle friendly NPC nameplates under MSUF Suite in Blizzard Key Bindings. Import protection keeps your current nameplates when importing a full Suite profile; explicit nameplate imports still replace them.", "Mapko usa barre dei nomi moderne, dimensione media e le stesse misure su Retail e Forever. Nomi di gilda e titoli influenzano anche i nomi nel mondo. Assegna Mostra/nascondi barre dei nomi dei PNG amici sotto MSUF Suite nei tasti di Blizzard. La protezione delle importazioni conserva le barre attuali quando importi un profilo Suite completo; le importazioni specifiche delle barre dei nomi le sostituiscono comunque.")
