T("Observed enemies adds up the enemy forces of the living enemies in combat that you see as a nameplate or target, and the total they would bring. Enemies that give no forces count as zero; while the client keeps a value hidden, the line shows -- instead of a guess. Enemies out of sight are not counted.", "Nemici osservati somma le forze nemiche dei nemici vivi in combattimento che vedi come barra del nome o bersaglio, e il totale che porterebbero. I nemici che non danno forze contano zero; finché il client nasconde un valore, la riga mostra -- invece di una stima. I nemici fuori vista non vengono contati.")
