T("One combined bag with a clear Suite background and item levels on equipment. Keep Blizzard's own item grid, or choose a Suite view with pages, bag groups or categories. Using and sorting items stays Blizzard's.", "Un'unica borsa unificata con uno sfondo Suite pulito e i livelli oggetto sull'equipaggiamento. Mantieni la griglia di oggetti di Blizzard o scegli una vista Suite con pagine, gruppi per borsa o categorie. L'uso e l'ordinamento degli oggetti restano di Blizzard.")
T("One of your Beacons is on nobody in the group.", "Uno dei tuoi Fari non è su nessuno del gruppo.")
T("One row", "Una riga")
T("Only a cooldown bar can take excess cooldowns.", "Solo una barra dei recuperi può ricevere quelli in eccesso.")
T("Only containers newly acquired after enabling this helper are opened. It waits for combat to end, opens one at a time, and leaves them to you while you hold Shift or a loot window or a window that gives item use another meaning is open: merchant, bank, guild bank, mail, trade, auction house, scrapper, socket, upgrade and similar. Warbound containers stay unopened unless you allow them; profiles that used this helper before keep opening them. Midnight Artisan payouts can wait while your Shard of Dundun is capped.", "Apre solo i contenitori ottenuti dopo l'attivazione di questa funzione. Attende la fine del combattimento, li apre uno alla volta e li lascia a te mentre tieni premuto Shift o è aperta una finestra del bottino o una finestra che dà un altro significato all'uso di un oggetto: mercante, banca, banca di gilda, posta, scambio, casa d'aste, smantellatore, incastonatura, potenziamento e simili. I contenitori della Brigata restano chiusi finché non li consenti; i profili che usavano già questa funzione continuano ad aprirli. I pagamenti degli artigiani di Midnight possono attendere finché le tue Schegge di Dundun sono al limite.")
T("Only in an active Delve and outside combat: if the player choice has exactly one enabled spell option, one button and no confirmation, MSUF selects it once. Other choices remain manual.", "Solo in una Scorribanda attiva e fuori dal combattimento: se la scelta ha esattamente un'opzione di incantesimo disponibile, un pulsante e nessuna conferma, MSUF la seleziona una sola volta. Le altre scelte restano manuali.")
T("Only inside instances", "Solo nelle istanze")
