T("Opens your character window, on the tab you used last, when an item upgrade merchant opens. It closes only a window this helper opened and waits for the end of combat to open or close it.", "Apre la finestra del personaggio, sull'ultima scheda usata, quando si apre un commerciante di potenziamenti di oggetti. Chiude solo una finestra aperta da questo aiutante e attende la fine del combattimento per aprirla o chiuderla.")
T("Optional Blizzard settings for chat, map, sound and low-health or alternate screen flashes. MSUF restores the previous value when you turn a choice or this helper off. Changes you make yourself in Blizzard settings while this helper runs are respected.", "Impostazioni facoltative di Blizzard per chat, mappa, audio e lampeggiamenti dello schermo per salute bassa o altre condizioni. MSUF ripristina il valore precedente quando disattivi una scelta o questa funzione. Le modifiche che apporti alle impostazioni di Blizzard durante l'uso vengono rispettate.")
T("Optional artwork and spacing controls. Use MSUF Edit Mode for position, nudging, reset, undo and redo.", "Controlli facoltativi di grafica e spaziatura. Usa la Modalità modifica di MSUF per posizione, spostamento fine, ripristino, annulla e ripeti.")
