T("Priority: focus, safe tank aggro, threat, tapped, quest, neutral, then NPC type. Turning focus off allows the next rule. Disabled threat overrides preserve Blizzard's active threat color. Tank mode uses your effective role; warnings also work for damage/healers. Secret values stay with Blizzard.", "Priorità: focus, aggro sicuro del tank, minaccia, reclamato, missione, neutrale, poi tipo di PNG. Disattivare il focus permette la regola successiva. Le sostituzioni di minaccia disattivate mantengono il colore di minaccia attivo di Blizzard. La modalità tank usa il tuo ruolo effettivo; gli avvisi funzionano anche per DPS/guaritori. I valori segreti restano a Blizzard.")
