T("Reminders appear only outside combat. The advance setting also shows active buffs, food and weapon enchants when their remaining time reaches the chosen number of minutes; 0 shows only missing effects. A single scheduled wakeup handles the next threshold. Reminders hide in arenas and battlegrounds, where aura data can be restricted.", "I promemoria appaiono solo fuori dal combattimento. L'impostazione di anticipo mostra anche buff attivi, cibo e incantamenti delle armi quando il tempo rimanente raggiunge il numero di minuti scelto; 0 mostra solo gli effetti mancanti. Un unico risveglio programmato gestisce la soglia successiva. I promemoria sono nascosti in arene e campi di battaglia, dove i dati delle aure possono essere limitati.")
T("Reminders for missing poisons and consumables.", "Promemoria per veleni e consumabili mancanti.")
