T("Repair", "Riparazione")
T("Repair equipment and sell poor-quality items when a merchant opens. Hold Shift to skip selling.", "Ripara l'equipaggiamento e vende gli oggetti di qualità scadente quando apri un mercante. Tieni premuto Maiusc per saltare la vendita.")
T("Repairs only when the cost is within your limit. Guild funds are used first when allowed.", "Ripara solo quando il costo rientra nel tuo limite. Se consentito, vengono usati prima i fondi della gilda.")
T("Replace Blizzard event banners", "Sostituisci banner eventi Blizzard")
T("Replace objectives with the Mythic+ timer during a key", "Sostituisci gli obiettivi con il timer Mitica+ durante una chiave")
T("Replaces the merchant's pages with one list; scroll it with the mouse wheel or the bar. Right-click buys, left-click picks an item up and Shift-click asks for a quantity; linking and previewing work as usual. Purchases paid with currencies or items, or costing at least 150 gold, ask for confirmation first. The buyback tab keeps Blizzard's layout. Drop or click an item from your bags onto the list to sell it; one you can still refund asks whether to refund it.", "Sostituisce le pagine del mercante con un unico elenco; scorrilo con la rotellina del mouse o la barra. Il clic destro acquista, il clic sinistro prende un oggetto e Maiusc-clic chiede una quantità; collegamenti e anteprime funzionano come al solito. Gli acquisti pagati con valute o oggetti, o che costano almeno 150 oro, chiedono prima una conferma. La scheda di riacquisto mantiene il layout di Blizzard. Trascina o fai clic con un oggetto delle borse sull'elenco per venderlo; se è ancora rimborsabile, chiede se rimborsarlo.")
T("Report junk sale requests in chat", "Segnala in chat le richieste di vendita cianfrusaglie")
T("Reports group member deaths in chat during combat.", "Segnala la morte dei membri del gruppo in chat durante il combattimento.")
T("Reports the first observed death of each group member during combat. Local chat, a screen notice and a sound can be selected separately. Simultaneous deaths share one sound. Optionally include your own death. The listener is active only while you are grouped and in combat.", "Segnala la prima morte osservata di ogni membro del gruppo durante il combattimento. Chat locale, avviso sullo schermo e suono si scelgono separatamente. Le morti simultanee condividono un solo suono. Puoi includere la tua morte. Il rilevamento è attivo solo in gruppo e in combattimento.")
T("Reputation", "Reputazione")
T("Request item levels of hovered players (sends inspect requests)", "Richiedi i livelli oggetto dei giocatori sotto il cursore (invia richieste di ispezione)")
T("Require a held modifier key before clicking Release Spirit in the death dialog.", "Richiedi di tenere premuto un modificatore per cliccare Rilascia spirito nella finestra di morte.")
