T("Restore these chat colors?", "Ripristinare questi colori della chat?")
T("Restores this bar's default spells and buffs for your specialization. Other bars and specializations stay as they are. You can undo it.", "Ripristina gli incantesimi e i buff predefiniti di questa barra per la tua specializzazione. Le altre barre e specializzazioni restano come sono. Puoi annullare l'operazione.")
T("Results and details", "Risultati e dettagli")
T("Resurrection offers", "Offerte di resurrezione")
T("Retail Druids only. Every incoming whisper in combat is a possible Innervate cue; message text cannot be inspected reliably during chat lockdown. The alert waits for a publicly known Innervate cooldown, or shows a generic cue when readiness is unavailable. A preferred target can be outlined on an MSUF group frame resolved outside combat. MSUF Edit Mode previews the alert and edits its position and size.", "Solo druidi Retail. Ogni sussurro ricevuto in combattimento è un possibile segnale per Stimolazione; il testo dei messaggi non può essere esaminato in modo affidabile durante il blocco della chat. L'avviso attende un tempo di recupero di Stimolazione noto pubblicamente, oppure mostra un segnale generico quando la disponibilità non è nota. Un bersaglio preferito può essere contornato su un riquadro di gruppo MSUF individuato fuori dal combattimento. La Modalità modifica di MSUF mostra un'anteprima dell'avviso e ne modifica posizione e dimensione.")
T("Retail only. Shows while Skyriding is available, or only in flight if selected. Choose bars or Blizzard Vigor gems; gem scale and a refill sound are optional. Separate bar heights, Surge icon size and speed-value offsets are under Text and bars. MSUF Edit Mode previews the HUD. Unknown charge values display as dashes.", "Solo Retail. Mostrato quando il volo dinamico è disponibile, oppure solo in volo se selezionato. Scegli barre o gemme di vigore Blizzard; scala e suono di ricarica sono opzionali. Altezze separate, dimensione dell’icona di impeto e scostamenti della velocità sono in Testo e barre. La modalità modifica MSUF mostra un’anteprima. Le cariche sconosciute sono trattini.")
T("Return to the current fight when combat starts", "Torna allo scontro attuale quando inizia il combattimento")
T("Returns this specialization to its short raid essentials list. Your other bars and specializations stay as they are. You can undo it.", "Riporta questa specializzazione al suo breve elenco di essenziali per incursione. Le altre barre e specializzazioni restano come sono. Puoi annullare l'operazione.")
T("Review and install", "Rivedi e installa")
T("Review the total cost, then learn available non-profession abilities at a trainer.", "Controlla il costo totale, poi apprendi le abilità non professionali disponibili presso un istruttore.")
