T("Selected currencies appear above the bag footer. Click Gold history for recorded character balances and 30 days of this character's income and spending, by local date. Other characters show their last recorded balance. The history starts when enabled and does not reconstruct earlier transactions; Clear saved character gold removes the history and the balances.", "Le valute selezionate appaiono sopra il piè di pagina delle borse. Clicca su Cronologia dell'oro per i saldi registrati dei personaggi e 30 giorni di entrate e uscite di questo personaggio, per data locale. Gli altri personaggi mostrano l'ultimo saldo registrato. La cronologia inizia all'attivazione e non ricostruisce le transazioni precedenti; Cancella i dati salvati sull'oro dei personaggi rimuove cronologia e saldi.")
