T("Show weather as text, an icon, or both. Choose Blizzard icons or original Forever artwork. The tooltip keeps the weather name when only the icon is shown.", "Mostra il meteo come testo, icona o entrambi. Scegli le icone Blizzard o la grafica originale Forever. Il nome del meteo rimane nel suggerimento quando viene mostrata solo l'icona.")
T("Show weekly reward item levels", "Mostra livelli oggetto ricompensa settimanale")
T("Show who each cast targets", "Mostra il bersaglio di ogni lancio")
T("Show windows", "Mostra finestre")
T("Show your Bloodlust exhaustion or ready state while grouped.", "Mostra il tuo esaurimento Sete di sangue o il tuo stato di pronto mentre sei in gruppo.")
T("Show your owned item count, including bank and Warband bank, on item tooltips.", "Mostra il conteggio degli oggetti che possiedi, inclusa la banca e la banca della banda da guerra, nei tooltip degli oggetti.")
T("Show your selected loot specialization in the Great Vault window.", "Mostra la specializzazione del bottino scelta nella finestra del Grande Forziere.")
T("Show zone", "Mostra zona")
T("Shown value", "Valore mostrato")
T("Shown windows: %d. Raise the number of windows to show this one.", "Finestre mostrate: %d. Aumenta il numero di finestre per mostrare questa.")
T("Shows Blizzard's shared battle resurrection charges in an active Mythic+ run or raid encounter. The icon counts down to the next charge using Blizzard's cooldown display. Hidden when the shared pool is unavailable. MSUF Edit Mode previews the display and edits X, Y, width, height and scale.", "Mostra le cariche condivise di resurrezione in combattimento di Blizzard in una corsa Mitica+ attiva o in uno scontro d'incursione. L'icona conta alla rovescia fino alla prossima carica usando la visualizzazione dei tempi di recupero di Blizzard. Nascosta quando la riserva condivisa non è disponibile. La Modalità modifica di MSUF mostra un'anteprima e ne modifica X, Y, larghezza, altezza e scala.")
T("Shows an approximate range to your current target from the game's range checks of spells you know; values include the target's hitbox, and dashes mean that no known spell can tell. Write the text with {range} and {unit}. The estimate can sit below the target frame, following it when the frame moves, or anywhere on screen; MSUF Edit Mode moves both placements.", "Mostra una distanza approssimativa dal bersaglio attuale in base ai controlli di portata del gioco per gli incantesimi che conosci; i valori includono l'area di impatto del bersaglio e i trattini indicano che nessun incantesimo conosciuto può stabilirla. Scrivi il testo con {range} e {unit}. La stima può stare sotto il riquadro del bersaglio, seguendolo quando il riquadro si sposta, oppure ovunque sullo schermo; la modalità modifica di MSUF sposta entrambe le posizioni.")
T("Shows item levels on merchant equipment when Blizzard has loaded its item data. Buyback items and items without an item level stay unchanged.", "Mostra i livelli oggetto sull'equipaggiamento dei mercanti quando Blizzard ne ha caricato i dati. Gli oggetti da riacquistare e quelli senza livello oggetto restano invariati.")
T("Shows the current loot specialization when you open the Great Vault. Updates if you change loot specialization while the window is open.", "Mostra la specializzazione del bottino attuale quando apri il Grande Forziere. Si aggiorna se cambi specializzazione del bottino mentre la finestra è aperta.")
T("Shows the lowest equipped durability below your chosen threshold, outside combat. MSUF Edit Mode shows a sample even when your gear is repaired. Its popup edits X, Y, width, height and scale.", "Mostra l'integrità più bassa dell'equipaggiamento sotto la soglia scelta, fuori dal combattimento. La Modalità modifica di MSUF mostra un esempio anche se l'equipaggiamento è riparato. Il suo popup modifica X, Y, larghezza, altezza e scala.")
T("Shows the number you own, including your bank and Warband bank, when the item tooltip has a public item ID. Optionally separate storage locations. Empty counts are omitted.", "Mostra il numero che possiedi, inclusa la tua banca e la banca della banda da guerra, quando il tooltip dell'oggetto ha un ID oggetto pubblico. Opzionalmente posizioni di archiviazione separate. I conteggi vuoti vengono omessi.")
T("Shows the total durability of your gear on the character model, moved by the two offsets, and crops the edges of the gear slot icons on your character sheet and in the Inspect window.", "Mostra la durabilità totale dell'equipaggiamento sul modello del personaggio, spostata dai due offset, e ritaglia i bordi delle icone degli slot nella scheda del personaggio e nella finestra di ispezione.")
T("Shows up to three extra compact notices for Blizzard personal item-loot toasts. Filter by minimum quality, mount or pet items, and optionally up to 100 item IDs. Native Blizzard notices remain visible; ordinary bag additions without a toast are not included.", "Mostra fino a tre avvisi compatti aggiuntivi per le notifiche di bottino personale di Blizzard. Filtra per qualità minima, oggetti cavalcatura o famiglio e, facoltativamente, fino a 100 ID oggetto. Le notifiche native di Blizzard restano visibili; le normali aggiunte alle borse senza notifica non sono incluse.")
T("Shows your current talent build and loot specialization on ready checks, when a dungeon queue pops, or when you enter an instance. It never changes your talents or loot spec.", "Mostra la configurazione dei talenti e la specializzazione del bottino attuali durante i controlli di prontezza, quando si apre la coda per una spedizione o quando entri in un'istanza. Non cambia mai i tuoi talenti o la specializzazione del bottino.")
T("Shows your most recent successful spells. Standard rows have an icon, name and marker; Icons only is a compact vertical icon column. Display width applies to standard rows; icon width follows row height in the icon preset. Position and anchor are set in MSUF Edit Mode, which shows sample actions. The list stops listening while disabled. Spells whose details the client keeps private cannot appear.", "Mostra i tuoi incantesimi riusciti più recenti. Le righe standard hanno un'icona, un nome e un indicatore; Solo icone è una colonna di icone verticale compatta. La larghezza di visualizzazione si applica alle righe standard; la larghezza dell'icona segue l'altezza della riga nella preimpostazione dell'icona. La posizione e l'ancoraggio vengono impostati nella modalità di modifica MSUF, che mostra azioni di esempio. L'elenco interrompe l'ascolto mentre è disabilitato. Gli incantesimi i cui dettagli il client mantiene privati ​​non possono apparire.")
T("Shows your own Bloodlust exhaustion while in a group, or a ready state if you prefer. Relevant player aura changes update it; MSUF Edit Mode moves it and previews the locked state.", "Mostra il tuo esaurimento Sete di sangue mentre sei in un gruppo o uno stato pronto, se preferisci. Le modifiche rilevanti all'aura del giocatore la aggiornano; La modalità modifica di MSUF lo sposta e visualizza in anteprima lo stato bloccato.")
