T("Start with a look, then tune its artwork, glow and plate. Changing a detail switches the preset label to Custom without losing the other settings.", "Parti da uno stile, poi regolane grafica, bagliore e lastra. Cambiare un dettaglio imposta l'etichetta della preimpostazione su Personalizzato senza perdere le altre impostazioni.")
