T("Static HUD surfaces are compiled out of combat. Dynamic meter rows never trigger skin mutations or queued work during combat. Meter windows opened later are styled after the next reload or when a setting on this page changes.", "Le superfici statiche dell'HUD vengono preparate fuori dal combattimento. Le righe dinamiche del misuratore non attivano mai modifiche alla skin né lavoro in coda durante il combattimento. Le finestre del misuratore aperte in seguito ricevono lo stile dopo il prossimo ricaricamento o quando cambia un'impostazione di questa pagina.")
