T("Switch between native tabs, combined bank, combined warbank and shared categories with the button below the bank window. Shared categories include accessible character and warbank tabs. Manage bank tabs returns to Blizzard purchases, deposits and tab settings. Every slot keeps its own item action and bank stacks are never merged; clicking a warband item selects Blizzard's Warband Bank tab first, and a refundable item asks before it enters the warband bank.", "Alterna tra schede native, banca unificata, banca della Brigata unificata e categorie condivise con il pulsante sotto la finestra della banca. Queste includono le schede accessibili del personaggio e della Brigata. Gestisci le schede della banca riapre acquisti, depositi e impostazioni di Blizzard. Ogni scomparto mantiene la propria azione e le pile in banca non vengono mai unite; un clic su un oggetto della Brigata seleziona prima la scheda Banca della Brigata di Blizzard, e un oggetto rimborsabile chiede conferma prima di entrare nella banca della Brigata.")
