T("Ten action bars plus stance and pet bars with free layout, paging, visibility rules and button styling. Key bindings keep using Blizzard's commands.", "Dieci barre delle azioni più le barre delle posture e del famiglio, con disposizione libera, cambio pagina, regole di visibilità e stile dei pulsanti. Le assegnazioni dei tasti continuano a usare i comandi di Blizzard.")
