T("The Glass material with MSUF Forever graphite, ivory and muted-gold colors.", "Il materiale Vetro con i colori grafite, avorio e oro tenue di MSUF Forever.")
T("The Great Vault is available only in Retail", "Il Grande Forziere è disponibile solo in Retail")
T("The Mapko skin for Blizzard nameplates. Blizzard keeps health, threat, casts, auras, selection and click handling.", "L'aspetto Mapko per le barre dei nomi Blizzard. Blizzard mantiene il controllo di salute, minaccia, lanci, aure, selezione e clic.")
T("The Suite Cooldown manager page (CDM) shows Blizzard's tracked cooldowns and buffs as bars you arrange and style freely.", "La pagina Gestore dei tempi di recupero (CDM) di Suite mostra i tempi di recupero e i benefici monitorati da Blizzard sotto forma di barre che puoi disporre e personalizzare liberamente.")
T("The Suite Minimap page styles the minimap itself: size, shape, border, zoom, buttons and info texts. MSUF's own minimap icon is under Miscellaneous.", "La pagina Minimappa di Suite personalizza la minimappa stessa: dimensioni, forma, bordo, zoom, pulsanti e testi informativi. L'icona della minimappa di MSUF si trova in Varie.")
T("The Suite Nameplates page styles Blizzard's enemy and friendly nameplates. MSUF's aura filters only decide whether nameplate-only auras show on MSUF frames.", "La pagina Barre dei nomi di Suite personalizza le barre dei nomi di nemici e alleati di Blizzard. I filtri delle aure di MSUF stabiliscono solo se le aure riservate alle barre dei nomi compaiono nei riquadri di MSUF.")
T("The Suite draws its own tracker and hides Blizzard's while it runs. Entries are sorted into groups: the focused quest, campaign and important quests, quests ready to hand in, regular quests, world quests, nearby bonus objectives, scenario and delve steps, and tracked achievements. In a raid it can hide completely, only while a boss is engaged, or pause the regular list during any raid fight; the encounter view keeps running then. Quest symbols come as Suite letters or as Blizzard's icons, and the heading line can be switched off. The key binding Use tracked quest item uses the focused quest's item, else the first usable one, and picks a new item only outside combat. Left-click a group name to fold it or a quest to open its log entry; right-click for more actions.", "La Suite disegna il proprio tracciamento e nasconde quello di Blizzard mentre è attiva. Le voci sono ordinate in gruppi: la missione selezionata, missioni della campagna e importanti, missioni pronte da consegnare, missioni normali, missioni mondiali, obiettivi bonus vicini, fasi di scenari e profondità, e imprese tracciate. In incursione può sparire del tutto, solo mentre un boss è ingaggiato o sospendere l’elenco normale durante qualsiasi combattimento d’incursione; la vista dello scontro continua a funzionare. I simboli delle missioni sono lettere Suite o icone Blizzard, e la riga d’intestazione si può disattivare. Il tasto rapido «Usa l’oggetto della missione tracciata» usa l’oggetto della missione selezionata, altrimenti il primo utilizzabile, e sceglie un nuovo oggetto solo fuori dal combattimento. Clic sinistro sul nome di un gruppo per comprimerlo o su una missione per aprirne la voce del registro; clic destro per altre azioni.")
T("The Suite frames Blizzard's original Micro Buttons. Their artwork, clicks, tooltips, enabled states and notifications stay native. Queue and FPS indicators stay at Blizzard's Edit Mode position. No recurring MSKIN update runs.", "La Suite incornicia i pulsanti originali del micromenu di Blizzard. Grafica, clic, tooltip, stati di attivazione e notifiche restano originali. Gli indicatori di coda e FPS restano nella posizione della Modalità modifica di Blizzard. Non viene eseguito alcun aggiornamento ricorrente di MSKIN.")
T("The Suite look gives Blizzard's dialogs a dark panel, and the Suite font sets their text font and size; each works alone, and without them dialogs keep Blizzard's look and fonts. A minimum height makes short dialogs taller once Blizzard has sized them; 0 keeps Blizzard's height. A custom position moves the first dialog and the ones Blizzard stacks below it; place it and set the height in MSUF Edit Mode.", "L'aspetto della Suite dà ai dialoghi Blizzard un pannello scuro e il carattere della Suite imposta carattere e dimensione del testo; ognuno funziona da solo e senza di essi i dialoghi mantengono aspetto e caratteri di Blizzard. Un'altezza minima rende più alti i dialoghi brevi dopo che Blizzard li ha dimensionati; 0 mantiene l'altezza di Blizzard. Una posizione personalizzata sposta il primo dialogo e quelli che Blizzard impila sotto; posizionalo e imposta l'altezza nella modalità di modifica di MSUF.")
T("The Suite skin engine is unavailable.", "Il motore skin della Suite non è disponibile.")
T("The chosen profile supplies all settings. Toggle which Suite modules are enabled in it.", "Il profilo scelto fornisce tutte le impostazioni. Scegli quali moduli della Suite sono attivi al suo interno.")
T("The class buff is included only when your character knows it. Enter self-buff spell IDs separated by spaces or commas. For a consumable, enter item ID:aura ID; separate pairs with commas. Up to 12 total reminders are shown. Weapon enchant items use the main-hand or off-hand enchant state.", "Il buff di classe è incluso solo se il tuo personaggio lo conosce. Inserisci gli ID degli incantesimi di buff personali separati da spazi o virgole. Per un consumabile, inserisci ID oggetto:ID aura; separa le coppie con virgole. Vengono mostrati fino a 12 promemoria in totale. Gli oggetti per incantare le armi usano lo stato dell'incantamento della mano primaria o secondaria.")
T("The combined bag and reagent bag use a Suite panel with a distinct header, border, and accent line. Set background opacity to 0 for a transparent window; item slots stay visible.", "La borsa unificata e la borsa dei reagenti usano un pannello Suite con intestazione, bordo e linea di risalto distinti. Imposta l'opacità dello sfondo a 0 per una finestra trasparente; gli slot degli oggetti restano visibili.")
T("The combined bag setting is protected on this client", "L'impostazione delle borse unificate è protetta su questo client")
T("The configuration cannot be opened during combat.", "La configurazione non può essere aperta in combattimento.")
T("The cooldown manager is not loaded.", "Il gestore tempi di recupero non è caricato.")
T("The cooldown manager needs an update. Reload the interface.", "Il gestore tempi di recupero richiede un aggiornamento. Ricarica l'interfaccia.")
T("The cooldown manager was reset: settings, spell lists and spell options.", "Il gestore tempi di recupero è stato ripristinato: impostazioni, elenchi e opzioni degli incantesimi.")
T("The countdown turns to the warning color below this many seconds. All bars: the Text section's setting.", "Il conto alla rovescia passa al colore di avviso sotto questo numero di secondi. Tutte le barre: impostazione della sezione Testo.")
T("The dark sweep over the icon while it counts down.", "L'ombreggiatura scura che scorre sull'icona durante il conto alla rovescia.")
T("The default font follows MSUF Fonts while the default size follows Blizzard's chat size. Choose Blizzard chat font to keep its own face. Slug has no shadow.", "Il carattere predefinito segue Caratteri MSUF, mentre la dimensione predefinita segue quella della chat di Blizzard. Scegli Carattere chat Blizzard per mantenerne il carattere. Slug non ha ombra.")
T("The dungeon's timer", "Il timer della spedizione")
T("The engine remains dormant until a lifecycle event or an explicit user action requires work.", "Il motore resta inattivo finché un evento del ciclo di vita o un'azione esplicita dell'utente non richiede lavoro.")
T("The global cooldown can leave the ring for a fixed circle of its own size and opacity, shown next to casts. Place it in MSUF Edit Mode; its button there works while this choice is on.", "Il tempo di recupero globale può lasciare l'anello per un cerchio fisso con dimensione e opacità proprie, mostrato accanto ai lanci. Posizionalo nella modalità modifica di MSUF; il suo pulsante lì funziona finché questa scelta è attiva.")
T("The header shows the meter and fight. Its buttons change the meter and fight directly in the window.", "L'intestazione mostra il misuratore e lo scontro. I suoi pulsanti cambiano misuratore e scontro direttamente nella finestra.")
T("The keystone notice remains local. The optional group announcement forwards only Blizzard's confirmed reset message immediately after your own reset request, while you are group leader. Failed attempts and resets by other players are not announced.", "L'avviso della chiave resta locale. L'annuncio facoltativo al gruppo inoltra solo il messaggio di ripristino confermato di Blizzard subito dopo la tua richiesta, se sei capogruppo. I tentativi falliti e i ripristini di altri giocatori non vengono annunciati.")
T("The macro builder is available only in Retail", "Il generatore di macro è disponibile solo in Retail")
T("The macro exceeds the 255-character limit", "La macro supera il limite di 255 caratteri")
T("The map grows or shrinks to the chosen width and height while the pointer is over it, then returns to its normal size. A circular map keeps its height equal to its width.", "La mappa si ingrandisce o si riduce alla larghezza e all'altezza scelte mentre il puntatore è sopra di essa, poi torna alla dimensione normale. Una mappa circolare mantiene l'altezza uguale alla larghezza.")
T("The merchant's offers changed; nothing was bought.", "Le offerte del mercante sono cambiate; non è stato acquistato nulla.")
T("The merchant's whole stock in one scrolling list with prices, quality colors and item levels.", "Tutta la merce del mercante in un elenco scorrevole con prezzi, colori di qualità e livelli oggetto.")
T("The minutes below", "I minuti qui sotto")
T("The mouse wheel zooms the map. Middle-click runs the chosen action; left and right clicks keep working as usual.", "La rotellina del mouse ingrandisce la mappa. Il clic centrale esegue l'azione scelta; i clic sinistro e destro funzionano come di consueto.")
T("The native input box keeps autocomplete, links and chat commands.", "La casella di input nativa mantiene completamento automatico, link e comandi della chat.")
T("The normal warning time", "Il normale tempo di avviso")
T("The optional glyph layer changes appearance while Blizzard keeps clicks, tooltips, enabled states and notifications. Queue and FPS indicators stay at Blizzard's Edit Mode position. No recurring MSKIN update runs.", "Il livello opzionale di glifi cambia l'aspetto mentre Blizzard mantiene clic, tooltip, stati di attivazione e notifiche. Gli indicatori di coda e FPS restano nella posizione della Modalità modifica di Blizzard. Non viene eseguito alcun aggiornamento ricorrente di MSKIN.")
T("The options module could not be loaded: %s", "Impossibile caricare il modulo delle opzioni: %s")
T("The options module did not finish initializing.", "Il modulo delle opzioni non ha completato l'inizializzazione.")
T("The party table grows in steps: characters with build and score, then the combat figures of Blizzard's damage meter, then the loot seen in chat. Each character keeps its latest runs; open the newest here or with /msufruns and step through older ones. Deleting a run asks for a second click. The card can wait until you close the chest's loot window.", "La tabella del gruppo cresce per passi: personaggi con assetto e punteggio, poi i dati di combattimento del misuratore dei danni di Blizzard, poi il bottino visto in chat. Ogni personaggio conserva le sue ultime spedizioni; apri la più recente qui o con /msufruns e scorri quelle precedenti. Eliminare una spedizione richiede un secondo clic. La scheda può attendere che tu chiuda la finestra del bottino del forziere.")
T("The preview and every section below edit this bar. Shared custom groups start with a separate list for explicit spell, aura and item IDs; disabling sharing restores the existing per-specialization list.", "L'anteprima e tutte le sezioni sottostanti modificano questa barra. I gruppi personalizzati condivisi iniziano con un elenco separato di ID espliciti di incantesimi, aure e oggetti; disattivando la condivisione si ripristina l'elenco esistente per specializzazione.")
T("The preview needs the cooldown manager.", "L'anteprima richiede il gestore tempi di recupero.")
T("The quick switch above remembers this mode when you turn the bar off. Choose Never to keep it hidden.", "L'interruttore rapido qui sopra ricorda questa modalità quando disattivi la barra. Scegli Mai per tenerla nascosta.")
T("The settings you change most. Attach the bar to another bar or to your player frame to keep them together; the gap is the space between them. Center keeps the first cooldown icon in the middle and adds the next icons right, left, right, left. Visible buffs stay compact; on a horizontal mixed bar, player and target buffs grow outward from the center on one row.", "Le impostazioni che cambi più spesso. Aggancia la barra a un'altra barra o al riquadro del giocatore per tenerle insieme; la distanza è lo spazio tra di esse. Centro mantiene la prima icona di recupero al centro e aggiunge le successive a destra, sinistra, destra, sinistra. I buff visibili restano compatti; su una barra mista orizzontale, i buff del giocatore e del bersaglio crescono verso l'esterno dal centro su un'unica riga.")
T("The socket window is available only in Retail", "La finestra socket è disponibile solo in Retail")
T("The stack condition uses Glow at stacks and Stack comparison. Buff absence cannot drive a combat glow through the native aura-slot API.", "La condizione usa il bagliore a un dato numero di accumuli e il confronto degli accumuli. L'assenza di un beneficio non può attivare un bagliore in combattimento tramite l'API nativa degli scomparti aura.")
T("Theme", "Tema")
T("Theme-colored icon outline", "Contorno dell'icona nel colore del tema")
T("These apply to every bar. The standalone assisted icon follows Blizzard's assisted combat highlight; enable that highlight in the game's Combat options. Its position is available in MSUF Edit Mode. Action bar presses show on cooldown icons only with the MSUF Suite action bars.", "Queste impostazioni si applicano a tutte le barre. L'icona indipendente segue l'evidenziazione dell'assistenza in combattimento di Blizzard; attivala nelle opzioni di Combattimento del gioco. La posizione si regola nella modalità di modifica di MSUF. Le pressioni della barra delle azioni appaiono sulle icone di recupero solo con le barre delle azioni di MSUF Suite.")
