T("Tick every demon you want out; demons your character has not learned yet can be ticked too. A summoned demon you left unticked gets a notice, as long as one of your ticked demons can be summoned. Another look of a demon counts as that demon once you have summoned it in that look.", "Spunta ogni demone che vuoi tenere fuori; puoi spuntare anche demoni che il tuo personaggio non ha ancora imparato. Un demone evocato senza spunta riceve un avviso, purché uno dei demoni spuntati si possa evocare. Un altro aspetto di un demone conta come quel demone appena lo hai evocato con quell'aspetto.")
