T("Timestamps use Blizzard's chat setting across all chat windows. Copy is off by default; when enabled, move its button with X/Y, choose a message, then press Ctrl+C. The displayed timestamp is included when timestamps are on. The message tools leave the Combat Log alone (its own settings can add a timestamp to every line); its lines still wake the idle fade. Saved history belongs to this character.", "Gli orari dei messaggi usano l'impostazione della chat di Blizzard in tutte le finestre della chat. Copia è disattivato per impostazione predefinita; se attivo, sposta il suo pulsante con X/Y, scegli un messaggio, poi premi Ctrl+C. L'orario visualizzato è incluso quando gli orari sono attivi. Gli strumenti dei messaggi non toccano il registro di combattimento (le sue impostazioni possono aggiungere l'orario a ogni riga); le sue righe risvegliano comunque la dissolvenza per inattività. La cronologia salvata appartiene a questo personaggio.")
