T("Turn off Show combat time to hide both the duration in every meter header and the separate floating timer. The two switches below let you show either one independently.", "Disattiva Mostra durata combattimento per nascondere sia la durata in ogni intestazione del misuratore sia il timer mobile separato. I due interruttori qui sotto ti permettono di mostrarli singolarmente.")
