T("Tutorials and help overlays", "Tutorial e guide in sovrimpressione")
T("Two rows", "Due righe")
T("Two-color material gradients", "Sfumature del materiale a due colori")
T("Type /keys or /msufkeys to see your own current keystone. Add party, raid or instance to share it in that channel. /keys group requests keys from group members running this Suite helper. The /keys alias is used only when another addon has not claimed it. Inside dungeons and raids Blizzard locks chat for addons; your key is then shown only to you.", "Digita /keys o /msufkeys per vedere la tua chiave mitica attuale. Aggiungi party, raid o instance per condividerla in quel canale. /keys group chiede le chiavi ai membri del gruppo che usano questo assistente di Suite. L'alias /keys viene usato solo se nessun altro addon lo ha registrato. Nelle spedizioni e nelle incursioni Blizzard blocca la chat per gli addon; la tua chiave viene allora mostrata solo a te.")
T("Type /msufguildprivacy or use the small ON/OFF button above the main chat window. Any chat window containing Guild or Officer is covered in full, including other channels in a mixed window. Click a cover to reveal the windows again. Messages keep arriving underneath.", "Digita /msufguildprivacy o usa il piccolo pulsante ON/OFF sopra la finestra principale della chat. Qualsiasi finestra di chat contenente Gilda o Ufficiale è coperta completamente, inclusi altri canali in una finestra mista. Fare clic su una copertina per rivelare nuovamente le finestre. I messaggi continuano ad arrivare sotto.")
T("Type /msufmacro to preview a mouseover ally, mouseover enemy or focus enemy macro. Enter a spell name or ID, then explicitly create a character macro outside combat. Drag it from /macro to your action bar.", "Digita /msufmacro per visualizzare l'anteprima di una macro per un alleato o un nemico sotto il cursore, oppure per un nemico in focus. Inserisci il nome o l'ID di un incantesimo, quindi crea la macro del personaggio fuori dal combattimento. Trascinala da /macro alla barra delle azioni.")
T("Type /msufraid to expand Blizzard's Raid Manager, /msufpull [1-60] for its native countdown, or /msufmark tank or /msufmark healer to mark one unambiguous party member. Optional automatic markers work only for one clear tank or healer in a five-player party, as leader or assistant. Existing and occupied markers are respected. Countdowns, markers and ready checks wait while Blizzard restricts them during combat, encounters and keystones; automatic markers try again afterwards.", "Digita /msufraid per espandere il gestore dell'incursione di Blizzard, /msufpull [1-60] per il suo conto alla rovescia nativo, oppure /msufmark tank o /msufmark healer per marcare un unico membro del gruppo senza ambiguità. I segnalini automatici facoltativi funzionano solo per un difensore o un guaritore ben definito in un gruppo da cinque, come capogruppo o assistente. I segnalini esistenti e occupati vengono rispettati. Conti alla rovescia, segnalini e appelli attendono finché Blizzard li limita in combattimento, negli scontri e nelle chiavi mitiche; i segnalini automatici riprovano dopo.")
T("Type /way x y for the current map or /way mapID x y. /msufway always works. The short /way alias is used only when no other addon owns it.", "Digita /way x y per la mappa corrente o /way mapID x y. /msufway funziona sempre. L'alias breve /way viene utilizzato solo quando nessun altro componente aggiuntivo lo possiede.")
T("Type a name or ID to filter", "Digita un nome o un ID per filtrare")
