T("Warn when your pet is missing or dead. By default, the missing warning applies to Hunters and Warlocks; the dead warning applies to any class with a pet. MSUF Edit Mode moves the alert.", "Avvisa quando il tuo famiglio è assente o morto. Per impostazione predefinita, l'avviso di assenza vale per Cacciatori e Stregoni; l'avviso di morte vale per qualsiasi classe con un famiglio. Puoi spostare l'avviso nella modalità modifica di MSUF.")
