T("When a Bloodlust-type buff from anyone in your group reaches you", "Quando ti raggiunge un beneficio come Brama di Sangue da chiunque nel tuo gruppo")
T("When a dungeon queue pops", "Quando si apre una coda nel dungeon")
T("When a ready check starts outside combat and your mana as a healer is low, a short note shows how much you have; it turns red below half of your limit. Only your own mana is read.", "Quando un appello inizia fuori dal combattimento e il tuo mana da guaritore è basso, una breve nota mostra quanto ne hai; diventa rossa sotto metà del tuo limite. Viene letto solo il tuo mana.")
T("When leaving", "All'uscita")
T("When someone offers you a resurrection, its dialog gets a green frame, optionally with Blizzard's ready check sound, and its accept button can get a green frame of its own. Accepting stays your click.", "Quando qualcuno ti offre una resurrezione, il suo dialogo riceve una cornice verde, facoltativamente con il suono dell'appello di Blizzard, e il suo pulsante Accetta può avere una propria cornice verde. Accettare resta un tuo clic.")
T("When the key ends", "Alla fine della chiave")
T("When the native group listing panel closes with applications still active, show their count in your own chat. Your applications remain active and no group chat is sent.", "Quando chiudi la finestra della ricerca gruppi con candidature ancora attive, mostra il loro numero nella tua chat. Le candidature restano attive e non viene inviato alcun messaggio nel gruppo.")
T("When the selected bar appears", "Quando appare la barra selezionata")
T("When this bar shows, and how far it fades out of combat. Tooltips show a spell when you hover its icon. This page and MSUF Edit Mode always show every bar.", "Quando questa barra è visibile e quanto sbiadisce fuori dal combattimento. I tooltip mostrano un incantesimo quando passi il mouse sulla sua icona. Questa pagina e la Modalità modifica di MSUF mostrano sempre tutte le barre.")
T("When to remind", "Quando ricordare")
T("When to show", "Quando mostrare")
T("When you earn an achievement", "Quando ottieni un'impresa")
T("When you gain a level", "Quando sali di livello")
T("When you or your pet cast Bloodlust or a similar haste spell", "Quando tu o il tuo famiglio lanciate Brama di Sangue o un incantesimo di celerità simile")
T("Where are the Suite minimap settings?", "Dove si trovano le impostazioni della minimappa di Suite?")
T("Where are the nameplate settings?", "Dove si trovano le impostazioni delle barre dei nomi?")
T("Where is the cooldown manager?", "Dove si trova il gestore dei tempi di recupero?")
T("Where the buff or debuff is looked for. Automatic: harmful spells on your target, all others on you.", "Dove viene cercato il buff o il debuff. Automatico: incantesimi dannosi sul tuo bersaglio, tutti gli altri su di te.")
T("Where to show recent actions", "Dove mostrare le azioni recenti")
T("Which number is drawn on top when both show.", "Quale numero è disegnato sopra quando appaiono entrambi.")
T("Which numbers show, which one is drawn on top, and their size and place. Single spells can differ: click them in the preview. The font settings below apply to every bar; Slug has no shadow.", "Quali numeri appaiono, quale è disegnato sopra, e la loro dimensione e posizione. I singoli incantesimi possono differire: fai clic su di essi nell'anteprima. Le impostazioni del carattere qui sotto valgono per ogni barra; Slug non ha ombra.")
T("While DataTexts and this choice are enabled, MSUF remembers this character's gold at login and after money changes. Hover a Gold or Session gold DataText to see the last known account total and up to eight other characters. No background scans are used.", "Quando i testi dati e questa opzione sono attivi, MSUF memorizza l'oro del personaggio all'accesso e dopo ogni variazione. Passa il cursore su un testo Oro o Oro della sessione per vedere l'ultimo totale noto dell'account e fino a otto altri personaggi. Non vengono eseguite scansioni in background.")
T("While DataTexts is active, hide Blizzard's backpack and bag slots. A Bag space DataText opens the native bags when clicked. Turn this off to restore the Blizzard buttons.", "Mentre il modulo Testi informativi è attivo, nasconde lo zaino e gli slot delle borse di Blizzard. Un testo informativo Spazio borse apre le borse native quando lo clicchi. Disattiva questa opzione per ripristinare i pulsanti di Blizzard.")
T("While a key runs, each defeated boss shows how far ahead or behind you are: against the best time you ever had on that boss, or against the boss times of your fastest completed run, at this keystone level or at any. Only runs this character completed count. With target times on, bosses still alive show the time to beat.", "Durante una chiave, ogni boss sconfitto mostra quanto sei avanti o indietro: rispetto al tuo miglior tempo su quel boss, o ai tempi dei boss della tua spedizione completata più veloce, a questo livello di chiave o a qualsiasi livello. Contano solo le spedizioni completate da questo personaggio. Con i tempi obiettivo attivi, i boss ancora vivi mostrano il tempo da battere.")
T("While the buff of this spell lasts, the icon shows its duration and stacks instead of the cooldown.", "Finché dura il buff di questo incantesimo, l'icona mostra la sua durata e i suoi accumuli al posto del tempo di recupero.")
