T("Windows update from the client's own combat data: every event outside combat, and at the chosen interval during combat.", "Le finestre si aggiornano dai dati di combattimento del client: a ogni evento fuori dal combattimento e all'intervallo scelto durante il combattimento.")
T("Wine-black panels with dusty rose controls.", "Pannelli nero vino con controlli rosa antico.")
T("WoW Forever only. Lists your group's threat on the watched enemy from Blizzard's threat data, highest first; for a friendly target, its enemy is used. Values the game keeps hidden are left out. Turn the mouse wheel over the window when more members are listed than rows fit. The red mark shows where you would take aggro, which is not the point where you match the tank. The meter repaints at most five times a second and reads no combat log.", "Solo WoW Forever. Elenca la minaccia del tuo gruppo sul nemico osservato dai dati di minaccia di Blizzard, dalla più alta; con un bersaglio amico si usa il suo nemico. I valori che il gioco nasconde sono omessi. Gira la rotellina sulla finestra quando sono elencati più membri delle righe disponibili. Il segno rosso indica dove prenderesti l'aggro, che non è il punto in cui raggiungi il difensore. Il misuratore si aggiorna al massimo cinque volte al secondo e non legge il registro di combattimento.")
