T("yd", "m")
T("• No idle OnUpdate; a window corner drag runs one only while the mouse button is held\n• No repeating tickers; short one-shot timers only batch layout and hover updates\n• One frame walk per session, when the window skin is first enabled, adopts existing panel buttons\n• No aura or nameplate listeners; unit events only for the Micro Bar portrait and open character panels\n• Combat-state events only pause and resume deferred work and close open option popups\n• One shared ADDON_LOADED dispatcher only while catalog targets are pending\n• External weak-key runtime state", "• Nessun OnUpdate a riposo; trascinare un angolo della finestra ne avvia uno solo finché il pulsante del mouse resta premuto\n• Nessun ticker ripetuto; brevi timer singoli raggruppano solo gli aggiornamenti di layout e di passaggio del mouse\n• Una sola scansione dei frame per sessione, alla prima attivazione della skin delle finestre, adotta i pulsanti dei pannelli esistenti\n• Nessun ascoltatore di aure o barre dei nomi; eventi di unità solo per il ritratto della barra micromenu e i pannelli del personaggio aperti\n• Gli eventi dello stato di combattimento mettono solo in pausa e riprendono il lavoro differito e chiudono i popup delle opzioni aperti\n• Un unico dispatcher ADDON_LOADED condiviso solo finché ci sono obiettivi del catalogo in attesa\n• Stato di esecuzione esterno con chiavi deboli")
